-- 0033 — PR 18: peças com os textos do escritório (pastas MODELOS DE PEÇAS / TÓPICOS / GESTÃO DE PASSIVOS BANCÁRIOS do Drive).
-- Tipos de peça: inicial revisional, embargos à execução, embargos monitórios, contestação (cobrança) + parecer. Partes por campo
-- ({{NOS}}/{{ELES}}), seções opcionais, numeração automática. Blocos do escritório substituem os rascunhos (só onde rascunho = true).
-- Idempotente. Depende de 0032.
alter table public.modelos_peca drop constraint if exists modelos_peca_tipo_check;
alter table public.modelos_peca add constraint modelos_peca_tipo_check check (tipo in ('inicial','embargos','monitoria','contestacao','parecer'));
alter table public.modelos_peca add column if not exists partes jsonb not null default '{"NOS":"Autora","ELES":"Réu"}'::jsonb, add column if not exists numerar boolean not null default false;
alter table public.blocos_tese drop constraint if exists blocos_tese_peca_check;
alter table public.blocos_tese add constraint blocos_tese_peca_check check (peca in ('inicial','embargos','monitoria','contestacao'));
update public.modelos_peca set partes = '{"NOS":"Autora","ELES":"Réu"}'::jsonb where id = 'inicial_revisional';
update public.modelos_peca set partes = '{"NOS":"Embargante","ELES":"Embargado"}'::jsonb where id = 'embargos_execucao';
update public.modelos_peca set partes = '{"NOS":"Cliente","ELES":"Banco"}'::jsonb where id = 'parecer_cliente';
update public.escritorio set dados = dados || '{"endereco":"Rua Jairo Amâncio de Castro, 2031, Centro","cidade":"Franca","uf":"SP","cep":"14400-324","telefone":"(16) 99354-7117"}'::jsonb, updated_at = now() where id = 'escritorio';
-- novas teses (tópicos do escritório)
insert into public.teses_revisionais (codigo, nome, grupo, verificacao, fundamento, descricao, acolhimento, alerta, ordem) values
  ('tarifa_nao_especificada', 'Tarifa não especificada embutida no financiamento', 'tarifas', 'auto', 'Arts. 4º, 6º, III, 46, 52 e 54, §4º, do CDC; Res. CMN 3.919/2010', 'Auto: valor em "Outras tarifas" sem identificação do serviço. Tarifa sem especificação viola o dever de informação e deve ser expurgada do valor financiado.', 'medio_alto', null, 125),
  ('inepcia_inicial', 'Inépcia da inicial — execução/monitória sem título ou demonstrativo', 'processual', 'manual', 'Art. 798, I, CPC; arts. 485, I, IV e VI, CPC; art. 700, §2º, CPC (monitória)', 'Verificar: contrato juntado diverso do mencionado, datas/valores divergentes, ausência de planilha discriminada da evolução do débito, extratos faltantes.', 'alto', 'Tese processual de maior acolhimento — ataca a cobrança antes do mérito.', 145),
  ('omissao_parcela', 'Omissão do valor da parcela no contrato', 'processual', 'auto_manual', 'Arts. 28 e 29 da Lei 10.931/2004; art. 52, I e V, CDC', 'Auto: parcela contratual não informada no formulário sugere verificação. Manual: o instrumento indica o valor de cada prestação ou os critérios para determiná-lo?', 'medio_alto', null, 155),
  ('cheque_especial_adimplemento', 'Uso do limite de cheque especial para pagar as parcelas', 'processual', 'manual', 'Art. 51, IV, CDC; art. 42, parágrafo único, CDC (devolução em dobro)', 'Verificar nos extratos: parcelas debitadas com uso do limite de cheque especial/conta garantida, gerando novo endividamento a juros superiores.', 'medio', null, 185),
  ('selic_cumulada', 'Indexação pela SELIC cumulada com juros remuneratórios', 'encargos', 'manual', 'Art. 51, IV e §1º, III, CDC; REsp 2.046.890/MG (2023); jurisprudência do STJ sobre bis in idem', 'Verificar no contrato: previsão simultânea de juros remuneratórios e de correção/indexação pela Taxa SELIC (que já embute remuneração).', 'medio', 'Comum em contratos do BB/Pronampe (TMS + spread). Só se aplica quando há juros remuneratórios além da SELIC.', 45),
  ('contratos_subjacentes', 'Revisão dos contratos subjacentes à renegociação', 'processual', 'manual', 'Súmula 286/STJ; arts. 360 e 367 CC', 'Verificar: o contrato é renegociação/confissão de dívida ("reorg", "renegociação", "composição")? Os contratos de origem podem ser revistos e exibidos.', 'medio_alto', 'Forte em contratos "GIRO REORG" e renegociações de limite.', 175)
on conflict (codigo) do update set nome = excluded.nome, grupo = excluded.grupo, verificacao = excluded.verificacao, fundamento = excluded.fundamento, descricao = excluded.descricao, acolhimento = excluded.acolhimento, alerta = excluded.alerta, ordem = excluded.ordem;
insert into public.modelos_peca (id, nome, tipo, descricao, ordem, secoes, partes, numerar) values ($t$embargos_execucao$t$, $t$Embargos à execução (título bancário)$t$, $t$embargos$t$, $t$Modelo do escritório: síntese dos fatos, justiça gratuita (opcional), Do Direito com os tópicos das teses, valor incontroverso, descaracterização da mora, constrição de valores (opcional), inversão do ônus, suspensão por revisional em trâmite (opcional), pedidos.$t$, 20, $t$[{"chave": "enderecamento", "titulo": "", "texto": "EXCELENTÍSSIMO(A) SENHOR(A) DOUTOR(A) JUIZ(A) DE DIREITO DA ___ VARA CÍVEL DA COMARCA DE {{comarca}}\n\nAutos nº {{processo}}"}, {"chave": "qualificacao", "titulo": "", "texto": "{{cliente.nome}}, pessoa jurídica de direito privado, inscrita no CNPJ sob o nº {{cliente.cnpj}}, com sede em {{cliente.endereco}}, {{cliente.cidade}}/{{cliente.uf}}, neste ato representada por {{cliente.representante}}, {{cliente.representante_qualificacao}}, inscrito(a) no CPF sob o nº {{cliente.representante_cpf}}, já qualificada nos autos da execução de título extrajudicial que lhe move {{banco}}, vem, respeitosamente, à presença de Vossa Excelência, por seus advogados que esta subscrevem (procuração anexa), com fundamento nos arts. 914 e seguintes do Código de Processo Civil, opor os presentes\n\nEMBARGOS À EXECUÇÃO\n\nem face de {{banco}}, instituição financeira inscrita no CNPJ sob o nº {{banco.cnpj}}, com sede em {{banco.endereco}}, pelos fatos e fundamentos jurídicos a seguir expostos:"}, {"chave": "fatos", "titulo": "Da Síntese dos fatos", "texto": "O {{ELES}} alega que é credor da {{NOS}} em razão de {{contrato.produto}} ({{contrato.numero}}), celebrado em {{contrato.data}}.\nAlega que a {{NOS}} é devedora do valor de {{valor_executado}}, decorrente de um empréstimo no valor de {{contrato.valor}} ({{contrato.valor_financiado}} financiados), a ser pago em {{contrato.prazo}} parcelas de {{contrato.parcela}}, com juros de {{contrato.taxa_mensal}} ao mês ({{contrato.taxa_anual}} ao ano).\n{{BLOCOS:fatos}}\nOs presentes embargos são tempestivos, pois opostos no prazo de 15 (quinze) dias contados da juntada do mandado de citação (art. 915 do CPC). Requer-se a atribuição de efeito suspensivo (art. 919, §1º, do CPC), uma vez que os fundamentos são relevantes e o prosseguimento da execução pode causar dano de difícil reparação — «indicar garantia do juízo ou justificar sua dispensa»."}, {"chave": "gratuidade", "titulo": "Da justiça gratuita", "texto": "Inicialmente, importa salientar que a requerente não tem condições de arcar com as despesas desta demanda. Desta maneira, vem requerer os benefícios da gratuidade da justiça, visto que não possui condições de se responsabilizar com as despesas processuais.\nNesse diapasão, importante considerar que o Código de Processo Civil ao revogar parte da Lei nº 1.060/50, instituiu, no art. 99, § 3º, a presunção de veracidade da declaração de pobreza de modo que não se exige do postulante à assistência judiciária gratuita que faça prova de sua miserabilidade, mas meramente que a declare.\nSendo assim, cumpre ressaltar que a possibilidade de concessão da assistência judiciária gratuita a pessoas jurídicas é objeto de Súmula do STJ, in verbis:\nSúmula 481 – “Faz jus ao benefício da justiça gratuita a pessoa jurídica com ou sem fins lucrativos que demonstrar sua impossibilidade de arcar com os encargos processuais.”\nDito isso, salvo circunstâncias especiais, nas quais há evidente demonstração da improcedência da alegada pobreza, em razão de sinais exteriores de riqueza, a mera petição da requerente basta para suprir a exigência legal no deferimento do benefício.\nAdemais, o referido pedido está preconizado no art. 98 e seguintes do Código de Processo Civil e no art. 5º da Constituição Federal, mais especificamente no inciso LXXIV, sendo esta benesse, garantia fundamental ao Estado Democrático de Direito.\nSalienta-se que tal pedido não está sendo feito com base na mera declaração de hipossuficiência da requerente, mas com base na real situação financeira, muito bem demonstrada pela dificuldade de arcar com pagamentos de dívidas.\nAnte ao exposto, roga-se pela concessão dos benefícios da gratuidade da justiça, com fulcro no artigo 98 e seguintes do Código de Processo Civil.", "opcional": true, "padrao": false}, {"chave": "direito", "titulo": "Do Direito", "texto": "{{BLOCOS:fundamentos}}"}, {"chave": "incontroverso", "titulo": "Do valor incontroverso do valor emprestado e do valor de parcela", "texto": "Demonstradas as abusividades cometidas pelo {{ELES}} no contrato, é possível estabelecer o valor incontroverso.\nPrimeiramente, devem ser expurgados do valor financiado os valores referentes a tarifas e seguros indevidos, de modo que o valor emprestado a ser considerado deve ser {{calc.valor_expurgado}}.\nAlém disso, deve ser desconsiderada a taxa constante do contrato e aplicada a taxa média de {{bacen.media_mensal}} ao mês. Desse modo, o valor da parcela deveria ser de {{calc.parcela_media}}.\nComparando a parcela do contrato ({{contrato.parcela}}) e a parcela apurada, a {{NOS}} pagaria, ao final, {{calc.dif_media}} a mais, gerando um lucro exorbitante ao {{ELES}} e uma onerosidade excessiva a si.\nA {{NOS}} junta aos autos planilha de cálculo, com a finalidade de auxiliar Vossa Excelência a visualizar de forma objetiva todas as abusividades impostas pelo {{ELES}}."}, {"chave": "constricao", "titulo": "Da eventual constrição de valores na conta da empresa {{NOS}}", "texto": "A) Do Princípio da Menor Onerosidade ao Devedor\nO princípio da menor onerosidade está expressamente previsto no art. 805 do Código de Processo Civil, o qual estabelece que quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo menos gravoso para o executado.\nNeste viés, a execução não deve ser compreendida como um instrumento de vingança privada, de modo que é indevido que o executado sofra mais do que o estritamente necessário na busca da satisfação do direito do exequente. Logo, gravames desnecessários à satisfação do direito devem ser evitados sempre que for possível satisfazer o direito por meio da utilização de outros mecanismos.\nÀ vista disso, mesmo que o executado se encontre em uma posição onde seu patrimônio esteja sujeito à execução e ele seja o sujeito passivo da demanda, o processo judicial almeja exclusivamente a satisfação do credor, não devendo assim as medidas necessárias irem além do estritamente necessário para se atingir o objetivo, uma vez que o ordenamento jurídico processual civil como um todo objetiva a reposição do equilíbrio e da lei, não o contrário.\nDessa forma, diante de uma eventual impossibilidade do devedor de satisfazer a obrigação devida através dos meios pretendidos pelo credor, o art. 805, em seu parágrafo único, oportuniza ao devedor a possibilidade de indicar outros meios mais eficazes e menos onerosos de garantir a execução não prejudicando assim o direito do credor. Vejamos.\nArt. 805. Quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo menos gravoso para o executado.\nParágrafo único. Ao executado que alegar ser a medida executiva mais gravosa incumbe indicar outros meios mais eficazes e menos onerosos, sob pena de manutenção dos atos executivos já determinados.\nAssim, a legislação processual civil brasileira garante que tanto o executado (devedor), quanto o exequente (credor) serão protegidos, pois é respeitado o limite do executado para a expropriação de seu bem, e é respeitado também o direito do exequente de satisfazer o seu direito.\nFeitas essas considerações, é imperioso que o presente caso seja analisado sob a óptica do referido princípio e dispositivo legal conforme será demonstrado.\nEm que pese ainda não tenha sido requerido o bloqueio das contas de titularidade da {{NOS}}, esta se adianta com o objetivo de proteger seus direitos e sua condição de existência, caso seja feito tal requerimento no futuro.\nPois bem, a {{NOS}} é uma empresa em plena atividade no mercado e que possui significativo número de funcionários, todos devidamente registrados em carteira dentro dos termos da lei.\nSendo assim, possui uma alta despesa mensal referente ao pagamento de salários e demais verbas trabalhistas de todos os seus colaboradores, totalizando um valor aproximado de «folha de pagamento mensal», conforme «documento» anexo.\nIsto posto, a possibilidade de a {{NOS}} eventualmente ter suas contas bancárias bloqueadas é completamente impensável, visto que tal fato a deixaria impossibilitada de arcar com o pagamento dos salários de seus colaboradores, bem como adimplir com suas responsabilidades ficais perante o Estado.\nNeste viés, destaca-se que as consequências de eventual constrição seriam catastróficas não só para a {{NOS}}, que caminharia a passos largos para o encerramento de suas atividades, mas como também para todos os seus funcionários que perderiam seus empregos, afetando diretamente suas condições de subsistência e de suas famílias.\nPortanto, desde já, a {{NOS}} pretende demonstrar que a determinação de eventual bloqueio de valores sobre suas contas bancárias seria uma medida absolutamente ilícita, de modo que contrariaria inclusive o entendimento jurisprudencial, que prioriza a proteção das condições de trabalho dos empregados. Veja-se:\n\"AGRAVO DE INSTRUMENTO – AÇÃO MONITÓRIA – FASE DE CUMPRIMENTO DE SENTENÇA – PENHORA – BLOQUEIO DE VALORES EM CONTA CORRENTE – IMPENHORABILIDADE – VALORES UTILIZADOS PARA PAGAMENTO DE SALÁRIOS DE FUNCIONÁRIOS – PRINCÍPIO DA MENOR ONEROSIDADE - Presente a comprovação, de que o bloqueio de valores existentes na conta corrente da empresa agravante, incidiu sobre valores que seriam destinados à folha de pagamento de funcionários da empresa – Verbas de natureza salarial pertencentes a terceiros, conforme descrito no inciso IV, do art. 833, do NCPC – Agravantes que indicaram outros bens móveis idôneos e suficientes à garantia parcial da dívida, com termo de caução lavrado sem recusa, em substituição aos ativos financeiros que foram levantados em razão de efeito ativo concedido por este E. TJSP – Bloqueio e consequente penhora incabíveis, vez que demonstrada hipótese de impenhorabilidade – Aplicação, ainda, dos art. 797 c.c. 805, caput e parágrafo único, 829, § 2º e 847, todos do NCPC – Precedentes deste E. TJSP – Precedentes - Bloqueio e penhora afastados – Efeito ativo confirmado – Decisão reformada – Agravo provido\".(TJ-SP - AI: 20114212620188260000 SP 2011421-26.2018.8.26.0000, Relator: Salles Vieira, Data de Julgamento: 19/12/2018, 24ª Câmara de Direito Privado, Data de Publicação: 19/12/2018)\nPENHORA. PENHORA \"ON LINE\". PESSOA JURÍDICA. VERBA DESTINADA PAGAMENTO DE SALÁRIO DE EMPREGADOS. IMPENHORABILIDADE. POSSIBILIDADE. NECESSIDADE DE PROVA. 1. Os embargos foram recebidos sem eficácia suspensiva e a devedora não pagou nem garantiu o juízo. 2. Demonstrado que o valor penhorado na conta da pessoa jurídica serviria para o pagamento de salários dos funcionários da devedora, esta não deve ser bloqueada. Os salários são impenhoráveis, mormente se pertencentes a terceiros alheios à dívida em questão. Recurso provido, com observação.(TJ-SP 21143512520188260000 SP 2114351-25.2018.8.26.0000, Relator: Melo Colombi, Data de Julgamento: 24/07/2018, 14ª Câmara de Direito Privado, Data de Publicação: 24/07/2018)\nAGRAVO DE INSTRUMENTO. EXECUÇÃO DE TÍTULO EXECUTIVO EXTRAJUDICIAL. IMPUGNAÇÃO AO BLOQUEIO JUDICIAL. PENHORA DE VALOR EM CONTA CORRENTE. IMPENHORABILIDADE. INTERPRETAÇÃO EXTENSIVA AO ART. 833, IV DO CPC. NECESSIDADE. ALEGAÇÃO DE DESTINAÇÃO AO PAGAMENTO DE SALÁRIO DE FUNCIONÁRIOS. DEMONSTRADA. DECISÃO PARCIALMENTE REFORMADA. 1. A norma do inciso IV do artigo 833 do Código de Processo Civil deve receber interpretação extensiva à luz da Constituição Federal primando pela função social da empresa, sobretudo pela proteção mínima do direito dos trabalhadores. 2. No caso em apreço a recorrente demonstrou satisfatoriamente que ao menos em parte, o valor da conta bloqueada serve para pagamento de seus funcionários e que os valores lá provisionados tinham o condão de saldar o débito trabalhista. 3. Agravo de Instrumento parcialmente provido. (TJPR - 16ª C.Cível - 0013386-13.2022.8.16.0000 - Curitiba - Rel.: DESEMBARGADOR PAULO CEZAR BELLIO - J. 27.06.2022)(TJ-PR - AI: 00133861320228160000 Curitiba 0013386-13.2022.8.16.0000 (Acórdão), Relator: Paulo Cezar Bellio, Data de Julgamento: 27/06/2022, 16ª Câmara Cível, Data de Publicação: 04/07/2022)\nSendo assim, resta claro e incontroverso que eventual constrição realizada prejudicaria sobremaneira a {{NOS}}, pois a aludida penhora recairia sobre suas contas bancárias e, consequentemente, sobre seus recursos financeiros, impossibilitando assim a manutenção de sua atividade empresarial, bem como pagamento dos seus funcionários e fornecedores, causando prejuízos que ultrapassariam os limites da presente demanda.\nPortanto, respeitando-se o Princípio da Menor Onerosidade e o disposto no art. 805 do CPC, a execução deve ser satisfeita mediante a penhora de outros bens pertencentes à empresa executada, conforme demais hipóteses elencadas no art. 835 do Código de Processo Civil, de modo a não causar demasiado prejuízo à {{NOS}}, por ser medida da mais lídima justiça.\nB) Da Violação ao Princípio da Função Social da Empresa\nA função social da empresa consiste em um princípio importante para o devido funcionamento da ordem econômica constitucional, além de contemplar diversas esferas da sociedade, como o meio ambiente, a propriedade privada, o direito dos trabalhadores, entre outros.\nNeste viés, a função social da empresa pode ser conceituada como um princípio que amplia e modifica os interesses e objetivo das sociedades empresárias.\nEste princípio está atrelado à função social da propriedade, trazida pelo artigo 170, inciso II, da Constituição Federal, visto que as empresas se constituem enquanto propriedade privada, devendo, portanto, exercerem sua função social.\nIsto posto, é imperioso destacar que a função social não se confunde com responsabilidade social, visto que, uma empresa socialmente responsável se constitui dessa maneira por mera liberalidade de seu empresário, enquanto que a função social é uma atribuição legislativa, portanto, obrigatória.\nNeste sentido, a adoção de medidas por empresas que visam atender sua função social é capaz de ocasionar diversos desdobramentos, quais sejam: a criação de empregos, pagamento de tributos, geração de riqueza, contribuição para o desenvolvimento econômico, social e cultural do entorno, respeito aos direitos dos consumidores, entre outros.\nSendo assim, a função social também é uma aliada dos empregados, uma vez que de acordo com as garantias previstas pelos artigos 170, inciso VIII e artigo 7º ambos da Constituição Federal, a função social trabalha na proteção dos direitos dos trabalhadores.\nEssa proteção se aplica a partir da garantia de um emprego pleno e digno, além de garantir os direitos fundamentais dos trabalhadores, como salário mínimo, 13º salário, entre outros.\nÀ vista disso, uma vez que esclarecida a importância da existência função social da empresa, é necessário destacar que a determinação de eventual bloqueio de valores nas contas bancárias da {{NOS}}, impossibilitaria a mesma de continuar exercendo sua função social, uma vez que estaria restringida de acessar seus ativos financeiros necessários para a manutenção da atividade empresarial.\nNeste viés, o encerramento das atividades da {{NOS}}, além de ocasionar prejuízo irreparável para a própria, também refletiria em graves prejuízos aos trabalhadores que perderiam seus empregos e, consequentemente não conseguiriam manter suas subsistências e as de suas famílias, ao desenvolvimento econômico da região onde se localiza a empresa, haja vista o aumento da taxa de desemprego, ao Estado que perderia uma fonte de pagamento de tributos, entre diversas outras situações.\nPortanto, não deve ser considerada em momento algum a legalidade de uma eventual constrição de valores nas contas bancárias da {{NOS}}, tendo que em vista que tal medida ocasionaria grave e irreparável violação ao Princípio da Função Social da Empresa, causando prejuízos que vão além do âmbito das partes da presente demanda.", "opcional": true, "padrao": true}, {"chave": "inversao", "titulo": "Da inversão do ônus da prova", "texto": "Claro está o abuso do poder econômico do {{ELES}} em detrimento da {{NOS}}, seja por impor cláusulas abusivas, seja por inserir valores reconhecidamente ilegais por nossos tribunais, o que nos leva a concluir pela presença do requisito verossimilhança das alegações.\nDiante da disparidade de forças, seja financeira e técnica, necessário a inversão do ônus da prova, consonante disposto no artigo 6º, inciso VIII, da Lei Consumerista.\nAdemais, a aplicação do Código de Defesa ao Consumidor aos contratos bancários, pacificados pela edição da Súmula 297 do STJ:\nSúmula 297 – “O Código de Defesa do Consumidor é aplicável às instituições financeiras”.\nPor atração do Código de Defesa ao Consumidor ao caso em tela, corolário lógico é que seja aplicada a inversão do ônus da prova.\nDesta forma, deve ser operada a inversão do ônus da prova, pois, in casu, encontram-se presente os dois requisitos referidos no artigo 6º, inciso VIII, do Código de Defesa do Consumidor ao deferimento da medida excepcional, restando o encargo de eventual fato não comprovado a demanda."}, {"chave": "suspensao", "titulo": "Da suspensão", "texto": "Importante mencionar que há ação revisional em trâmite sob o nº «número da ação revisional», que interferirá diretamente no resultado deste. É possível a conexão entre um processo de conhecimento e um de execução, quando se observar entre eles uma mesma origem, ou seja, que as causas se fundamentam em fatos comuns ou nas mesmas relações jurídicas, sujeitando-as a uma análise conjunta. Conforme jurisprudência:\n\"AGRAVO DE INSTRUMENTO – AÇÃO DE EXECUÇÃO - EMBARGOS À EXECUÇÃO – AÇÃO REVISIONAL PROPOSTA E PENDENTE DE JULGAMENTO – PREJUDICIALIDADE – CONEXÃO - SUSPENSÃO DA EXECUÇÃO – I - Existência de ação revisional ajuizada, em que se discute a validade de diversos títulos, entre os quais o título objeto da ação de execução e dos embargos à execução - Reconhecida a conexão por prejudicialidade entre as demandas – Possibilidade de decisões conflitantes – Inteligência do art. 55, caput, §§s 1º e 2º, I, do NCPC – II - Estando em discussão o título, em sede de ação revisional, é cabível a suspensão da execução, ante a clareza do disposto no art. 313, inciso V, letra 'a', do NCPC – O ajuizamento de ação revisional, cujo objetivo é a discussão do débito exequendo, exerce perante a execução inegável influência prejudicial – Decisão a ser proferida no processo revisional que poderá implicar em eventual redução ou extinção do montante do débito - Inaplicabilidade dos arts. 776 e 784, § 1º, do NCPC, pois a regra geral não prevalece sobre a regra especial (princípio da especialidade) – Hipótese que não se confunde com o art. 919, § 1º, do NCPC - Precedentes deste E. TJ e desta C. 24ª Câmara de Direito Privado – Suspensão da ação de execução reconhecida – Decisão mantida - Agravo improvido.\"\n(TJ-SP 22075157820178260000 SP 2207515-78.2017.8.26.0000, Relator: Salles Vieira, Data de Julgamento: 29/06/2018, 24ª Câmara de Direito Privado, Data de Publicação: 29/06/2018)\nAGRAVO DE INSTRUMENTO. REVISIONAL DE CONTRATO E EXECUÇÃO DE TÍTULO EXTRAJUDICIAL. CONEXÃO. SUSPENSÃO DA EXECUÇÃO ATÉ O TRÂNSITO EM JULGADO DA REVISIONAL DE CONTRATO CUJO TÍTULO EXEQUENDO EM LITÍGIO INTEGRA AÇÃO REVISIONAL DISTINTA. PREJUDICIALIDADE EXTERNA CONFIGURADA. POSSIBILIDADE DA SUSPENSÃO PARA SE EVITAR DECISÕES CONFLITANTES. DECISÃO MANTIDA. RECURSO DESPROVIDO. Conexas as demandas, por cautela cumpre a diligente suspensão da execução até o trânsito em julgado da ação revisional e dos embargos à execução, evitando-se assim, decisões conflitantes. (TJPR - 16ª C.Cível - 0060150-62.2019.8.16.0000 - Loanda - Rel.: Desembargador Luiz Antônio Barry - J. 25.05.2020)\n(TJ-PR - AI: 00601506220198160000 PR 0060150-62.2019.8.16.0000 (Acórdão), Relator: Desembargador Luiz Antônio Barry, Data de Julgamento: 25/05/2020, 16ª Câmara Cível, Data de Publicação: 26/05/2020)\nAGRAVO DE INSTRUMENTO – AÇÃO REVISIONAL DE CONTRATO – DECISÃO AGRAVADA QUE RECONHECEU A CONEXÃO DOS PRESENTES AUTOS COM OS AUTOS DE EXECUÇÃO E DE EMBARGOS À EXECUÇÃO DE TÍTULO EXTRAJUDICIAL. 1. Ação Revisional, Execução de Título Extrajudicial e Embargos à Execução de Título Extrajudicial que possuem como objeto o mesmo contrato - Identidade de partes - Mesma relação contratual – Risco de decisões conflitantes – Conexão - Aplicação do Art. 55, § 3º, do CPC. 2. Decisão mantida. RECURSO NÃO PROVIDO. (TJPR - 14ª C.Cível - 0024294-66.2021.8.16.0000 - Londrina - Rel.: DESEMBARGADOR OCTAVIO CAMPOS FISCHER - J. 30.10.2021)\n(TJ-PR - AI: 00242946620218160000 Londrina 0024294-66.2021.8.16.0000 (Acórdão), Relator: Octavio Campos Fischer, Data de Julgamento: 30/10/2021, 14ª Câmara Cível, Data de Publicação: 03/11/2021)\nSendo assim requer a conexão das ações com efeito suspensivo da ação de execução até o final do julgamento da ação revisional, com fulcro no art. 55, caput, parágrafo 1º e 2, art. 313, V, a, do Código de Processo Civil e entendimento do Tribunal.", "opcional": true, "padrao": false}, {"chave": "pedidos", "titulo": "Dos Pedidos", "texto": "Diante de todo o exposto, requer:\n\nO deferimento do benefício da Justiça Gratuita em favor da {{NOS}}, conforme artigo 98 e seguintes do Código de Processo Civil e, subsidiariamente, caso não seja concedido tal benefício, que as custas sejam recolhidas ao final do processo;\nO recebimento dos embargos com efeito suspensivo, nos termos do art. 919, §1º, do CPC;\nA intimação do {{ELES}} para, querendo, apresentar impugnação;\nA inversão do ônus da prova, nos termos do artigo 6º, VIII, do Código de Defesa do Consumidor, para determinar a revisão do contrato objeto da presente demanda;\n{{BLOCOS:pedidos}}\nQue não seja concedido eventual pedido de constrição de valores nas contas bancárias de titularidade da {{NOS}}, por ser medida extremamente gravosa que atentaria contra o Princípio da Menor Onerosidade e o Princípio da Função Social da Empresa, devendo ser utilizado outro meio para satisfazer a dívida, nos termos do art. 835 do Código de Processo Civil;\nSubsidiariamente, o acolhimento dos embargos para reconhecer o excesso de execução, reduzindo o débito ao valor apurado em perícia contábil, com a produção de prova pericial e a exibição dos extratos e da planilha de evolução do débito;\nQue seja o {{ELES}} condenado ao pagamento das custas e despesas processuais, bem como de honorários advocatícios de sucumbência;\n\nProtesta provar o alegado através de todos os meios de prova admitidos em direito.\nDá-se à causa o valor de {{valor_causa}}.\n\nTermos em que,\npede deferimento.\n\n{{escritorio.cidade}}/{{escritorio.uf}}, {{hoje}}.\n\n{{advogado.nome}}\n{{advogado.oab}}"}, {"chave": "provas", "titulo": "ROL DE DOCUMENTOS", "texto": "1. Procuração e atos constitutivos;\n2. Cópia do título executado e da planilha apresentada pelo credor;\n3. Demonstrativo do valor que a {{NOS}} entende devido (art. 917, §3º, do CPC);\n4. Relatório de revisão contratual com a taxa média do Banco Central (série {{bacen.serie}} — {{bacen.nome}}, {{bacen.mes}});\n{{BLOCOS:provas}}"}]$t$::jsonb, $t${"NOS": "Embargante", "ELES": "Embargado"}$t$::jsonb, true)
on conflict (id) do update set nome = excluded.nome, tipo = excluded.tipo, descricao = excluded.descricao, ordem = excluded.ordem, secoes = excluded.secoes, partes = excluded.partes, numerar = excluded.numerar, updated_at = now();
insert into public.modelos_peca (id, nome, tipo, descricao, ordem, secoes, partes, numerar) values ($t$embargos_monitorios$t$, $t$Embargos monitórios (ação monitória bancária)$t$, $t$monitoria$t$, $t$Mesma estrutura dos embargos à execução, adaptada à ação monitória (art. 702 do CPC): inépcia por falta de demonstrativo/extratos, Do Direito com as teses, valor incontroverso, descaracterização da mora, inversão do ônus, pedidos.$t$, 25, $t$[{"chave": "enderecamento", "titulo": "", "texto": "EXCELENTÍSSIMO(A) SENHOR(A) DOUTOR(A) JUIZ(A) DE DIREITO DA ___ VARA CÍVEL DA COMARCA DE {{comarca}}\n\nAutos nº {{processo}}\nAção monitória"}, {"chave": "qualificacao", "titulo": "", "texto": "{{cliente.nome}}, pessoa jurídica de direito privado, inscrita no CNPJ sob o nº {{cliente.cnpj}}, com sede em {{cliente.endereco}}, {{cliente.cidade}}/{{cliente.uf}}, neste ato representada por {{cliente.representante}}, {{cliente.representante_qualificacao}}, inscrito(a) no CPF sob o nº {{cliente.representante_cpf}}, já qualificada nos autos da ação monitória que lhe move {{banco}}, vem, respeitosamente, à presença de Vossa Excelência, por seus advogados que esta subscrevem (procuração anexa), com fundamento no art. 702 do Código de Processo Civil, opor os presentes\n\nEMBARGOS MONITÓRIOS\n\nem face de {{banco}}, instituição financeira inscrita no CNPJ sob o nº {{banco.cnpj}}, com sede em {{banco.endereco}}, pelos fatos e fundamentos jurídicos a seguir expostos:"}, {"chave": "fatos", "titulo": "Da Síntese dos fatos", "texto": "O {{ELES}} alega que é credor da {{NOS}} em razão de {{contrato.produto}} ({{contrato.numero}}), celebrado em {{contrato.data}}, e pretende a constituição de título executivo judicial no valor de {{valor_executado}}, decorrente de um empréstimo no valor de {{contrato.valor}} ({{contrato.valor_financiado}} financiados), a ser pago em {{contrato.prazo}} parcelas de {{contrato.parcela}}, com juros de {{contrato.taxa_mensal}} ao mês ({{contrato.taxa_anual}} ao ano).\n{{BLOCOS:fatos}}\nOs presentes embargos são tempestivos, pois opostos no prazo de 15 (quinze) dias contados da citação (art. 702 do CPC), independentemente de garantia do juízo."}, {"chave": "gratuidade", "titulo": "Da justiça gratuita", "texto": "Inicialmente, importa salientar que a requerente não tem condições de arcar com as despesas desta demanda. Desta maneira, vem requerer os benefícios da gratuidade da justiça, visto que não possui condições de se responsabilizar com as despesas processuais.\nNesse diapasão, importante considerar que o Código de Processo Civil ao revogar parte da Lei nº 1.060/50, instituiu, no art. 99, § 3º, a presunção de veracidade da declaração de pobreza de modo que não se exige do postulante à assistência judiciária gratuita que faça prova de sua miserabilidade, mas meramente que a declare.\nSendo assim, cumpre ressaltar que a possibilidade de concessão da assistência judiciária gratuita a pessoas jurídicas é objeto de Súmula do STJ, in verbis:\nSúmula 481 – “Faz jus ao benefício da justiça gratuita a pessoa jurídica com ou sem fins lucrativos que demonstrar sua impossibilidade de arcar com os encargos processuais.”\nDito isso, salvo circunstâncias especiais, nas quais há evidente demonstração da improcedência da alegada pobreza, em razão de sinais exteriores de riqueza, a mera petição da requerente basta para suprir a exigência legal no deferimento do benefício.\nAdemais, o referido pedido está preconizado no art. 98 e seguintes do Código de Processo Civil e no art. 5º da Constituição Federal, mais especificamente no inciso LXXIV, sendo esta benesse, garantia fundamental ao Estado Democrático de Direito.\nSalienta-se que tal pedido não está sendo feito com base na mera declaração de hipossuficiência da requerente, mas com base na real situação financeira, muito bem demonstrada pela dificuldade de arcar com pagamentos de dívidas.\nAnte ao exposto, roga-se pela concessão dos benefícios da gratuidade da justiça, com fulcro no artigo 98 e seguintes do Código de Processo Civil.", "opcional": true, "padrao": false}, {"chave": "preliminar", "titulo": "Preliminarmente — da ausência de demonstrativo do débito e dos extratos", "texto": "A ação monitória fundada em contrato bancário exige prova escrita da dívida e demonstrativo discriminado da sua evolução (art. 700, §2º, I, do CPC; Súmula 247/STJ: o contrato de abertura de crédito em conta corrente, acompanhado do demonstrativo de débito, constitui documento hábil para o ajuizamento da ação monitória). «Descrever o que falta: contrato, extratos desde a origem, planilha de evolução, divergências de valores.»\nOutrossim, compulsando os autos, constata-se que, além da ausência de contrato firmado entre as partes, há flagrante irregularidade quanto aos demais documentos acostados aos autos, em especial, quanto à evolução da dívida.\nVeja-se que o {{ELES}} tão somente acostou o que seria o valor devido corrigido e os critérios supostamente utilizados para a atualização do montante em {{valor_executado}}:\n«inserir o demonstrativo apresentado»\nNão há sequer como apurar se a taxa de juros aplicada foi realmente de {{contrato.taxa_mensal}} a.m. e {{contrato.taxa_anual}} a.a., uma vez que se desconhece o valor base utilizado para cálculo da aplicação dos juros.\nAssim, fica a {{NOS}} totalmente impossibilitada de apurar como se deu a incidência dos juros no saldo devedor.\nRepita-se: o demonstrativo do débito deve expor a evolução da dívida de maneira clara, com todas as amortizações, juros cobrados, correção monetária etc. Isso mês a mês, até a propositura da ação. No contexto, não se sabe minimamente quais critérios foram utilizados para se chegar ao valor final do débito; muito menos comprovantes de sua evolução.\nApenas com a documentação apresentada pelo {{ELES}}, mostra-se inviável demonstrar pormenorizadamente as ilegalidades na cobrança dos valores, tais como abusividade nas taxas de juros praticadas, existência de encargos cobrados indevidamente, entre outros.\nDessa forma, no presente caso, não sendo possível analisar as condições iniciais contratadas, bem como a existência de encargos e cobranças indevidas que foram pactuadas no contrato, não há como se apurar o valor devido.\nApenas com a documentação trazida pelo {{ELES}} junto à inicial, fica a {{NOS}} totalmente limitada, podendo ser condenada ao pagamento de uma dívida eivada de vícios e, portanto, nula de pleno direito, razão pela qual improcede a presente demanda por absoluta falta de provas.", "opcional": true, "padrao": true}, {"chave": "direito", "titulo": "Do Direito", "texto": "{{BLOCOS:fundamentos}}"}, {"chave": "incontroverso", "titulo": "Do valor incontroverso do valor emprestado e do valor de parcela", "texto": "Demonstradas as abusividades cometidas pelo {{ELES}} no contrato, é possível estabelecer o valor incontroverso.\nPrimeiramente, devem ser expurgados do valor financiado os valores referentes a tarifas e seguros indevidos, de modo que o valor emprestado a ser considerado deve ser {{calc.valor_expurgado}}.\nAlém disso, deve ser desconsiderada a taxa constante do contrato e aplicada a taxa média de {{bacen.media_mensal}} ao mês. Desse modo, o valor da parcela deveria ser de {{calc.parcela_media}}.\nComparando a parcela do contrato ({{contrato.parcela}}) e a parcela apurada, a {{NOS}} pagaria, ao final, {{calc.dif_media}} a mais, gerando um lucro exorbitante ao {{ELES}} e uma onerosidade excessiva a si.\nA {{NOS}} junta aos autos planilha de cálculo, com a finalidade de auxiliar Vossa Excelência a visualizar de forma objetiva todas as abusividades impostas pelo {{ELES}}."}, {"chave": "constricao", "titulo": "Da eventual constrição de valores na conta da empresa {{NOS}}", "texto": "A) Do Princípio da Menor Onerosidade ao Devedor\nO princípio da menor onerosidade está expressamente previsto no art. 805 do Código de Processo Civil, o qual estabelece que quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo menos gravoso para o executado.\nNeste viés, a execução não deve ser compreendida como um instrumento de vingança privada, de modo que é indevido que o executado sofra mais do que o estritamente necessário na busca da satisfação do direito do exequente. Logo, gravames desnecessários à satisfação do direito devem ser evitados sempre que for possível satisfazer o direito por meio da utilização de outros mecanismos.\nÀ vista disso, mesmo que o executado se encontre em uma posição onde seu patrimônio esteja sujeito à execução e ele seja o sujeito passivo da demanda, o processo judicial almeja exclusivamente a satisfação do credor, não devendo assim as medidas necessárias irem além do estritamente necessário para se atingir o objetivo, uma vez que o ordenamento jurídico processual civil como um todo objetiva a reposição do equilíbrio e da lei, não o contrário.\nDessa forma, diante de uma eventual impossibilidade do devedor de satisfazer a obrigação devida através dos meios pretendidos pelo credor, o art. 805, em seu parágrafo único, oportuniza ao devedor a possibilidade de indicar outros meios mais eficazes e menos onerosos de garantir a execução não prejudicando assim o direito do credor. Vejamos.\nArt. 805. Quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo menos gravoso para o executado.\nParágrafo único. Ao executado que alegar ser a medida executiva mais gravosa incumbe indicar outros meios mais eficazes e menos onerosos, sob pena de manutenção dos atos executivos já determinados.\nAssim, a legislação processual civil brasileira garante que tanto o executado (devedor), quanto o exequente (credor) serão protegidos, pois é respeitado o limite do executado para a expropriação de seu bem, e é respeitado também o direito do exequente de satisfazer o seu direito.\nFeitas essas considerações, é imperioso que o presente caso seja analisado sob a óptica do referido princípio e dispositivo legal conforme será demonstrado.\nEm que pese ainda não tenha sido requerido o bloqueio das contas de titularidade da {{NOS}}, esta se adianta com o objetivo de proteger seus direitos e sua condição de existência, caso seja feito tal requerimento no futuro.\nPois bem, a {{NOS}} é uma empresa em plena atividade no mercado e que possui significativo número de funcionários, todos devidamente registrados em carteira dentro dos termos da lei.\nSendo assim, possui uma alta despesa mensal referente ao pagamento de salários e demais verbas trabalhistas de todos os seus colaboradores, totalizando um valor aproximado de «folha de pagamento mensal», conforme «documento» anexo.\nIsto posto, a possibilidade de a {{NOS}} eventualmente ter suas contas bancárias bloqueadas é completamente impensável, visto que tal fato a deixaria impossibilitada de arcar com o pagamento dos salários de seus colaboradores, bem como adimplir com suas responsabilidades ficais perante o Estado.\nNeste viés, destaca-se que as consequências de eventual constrição seriam catastróficas não só para a {{NOS}}, que caminharia a passos largos para o encerramento de suas atividades, mas como também para todos os seus funcionários que perderiam seus empregos, afetando diretamente suas condições de subsistência e de suas famílias.\nPortanto, desde já, a {{NOS}} pretende demonstrar que a determinação de eventual bloqueio de valores sobre suas contas bancárias seria uma medida absolutamente ilícita, de modo que contrariaria inclusive o entendimento jurisprudencial, que prioriza a proteção das condições de trabalho dos empregados. Veja-se:\n\"AGRAVO DE INSTRUMENTO – AÇÃO MONITÓRIA – FASE DE CUMPRIMENTO DE SENTENÇA – PENHORA – BLOQUEIO DE VALORES EM CONTA CORRENTE – IMPENHORABILIDADE – VALORES UTILIZADOS PARA PAGAMENTO DE SALÁRIOS DE FUNCIONÁRIOS – PRINCÍPIO DA MENOR ONEROSIDADE - Presente a comprovação, de que o bloqueio de valores existentes na conta corrente da empresa agravante, incidiu sobre valores que seriam destinados à folha de pagamento de funcionários da empresa – Verbas de natureza salarial pertencentes a terceiros, conforme descrito no inciso IV, do art. 833, do NCPC – Agravantes que indicaram outros bens móveis idôneos e suficientes à garantia parcial da dívida, com termo de caução lavrado sem recusa, em substituição aos ativos financeiros que foram levantados em razão de efeito ativo concedido por este E. TJSP – Bloqueio e consequente penhora incabíveis, vez que demonstrada hipótese de impenhorabilidade – Aplicação, ainda, dos art. 797 c.c. 805, caput e parágrafo único, 829, § 2º e 847, todos do NCPC – Precedentes deste E. TJSP – Precedentes - Bloqueio e penhora afastados – Efeito ativo confirmado – Decisão reformada – Agravo provido\".(TJ-SP - AI: 20114212620188260000 SP 2011421-26.2018.8.26.0000, Relator: Salles Vieira, Data de Julgamento: 19/12/2018, 24ª Câmara de Direito Privado, Data de Publicação: 19/12/2018)\nPENHORA. PENHORA \"ON LINE\". PESSOA JURÍDICA. VERBA DESTINADA PAGAMENTO DE SALÁRIO DE EMPREGADOS. IMPENHORABILIDADE. POSSIBILIDADE. NECESSIDADE DE PROVA. 1. Os embargos foram recebidos sem eficácia suspensiva e a devedora não pagou nem garantiu o juízo. 2. Demonstrado que o valor penhorado na conta da pessoa jurídica serviria para o pagamento de salários dos funcionários da devedora, esta não deve ser bloqueada. Os salários são impenhoráveis, mormente se pertencentes a terceiros alheios à dívida em questão. Recurso provido, com observação.(TJ-SP 21143512520188260000 SP 2114351-25.2018.8.26.0000, Relator: Melo Colombi, Data de Julgamento: 24/07/2018, 14ª Câmara de Direito Privado, Data de Publicação: 24/07/2018)\nAGRAVO DE INSTRUMENTO. EXECUÇÃO DE TÍTULO EXECUTIVO EXTRAJUDICIAL. IMPUGNAÇÃO AO BLOQUEIO JUDICIAL. PENHORA DE VALOR EM CONTA CORRENTE. IMPENHORABILIDADE. INTERPRETAÇÃO EXTENSIVA AO ART. 833, IV DO CPC. NECESSIDADE. ALEGAÇÃO DE DESTINAÇÃO AO PAGAMENTO DE SALÁRIO DE FUNCIONÁRIOS. DEMONSTRADA. DECISÃO PARCIALMENTE REFORMADA. 1. A norma do inciso IV do artigo 833 do Código de Processo Civil deve receber interpretação extensiva à luz da Constituição Federal primando pela função social da empresa, sobretudo pela proteção mínima do direito dos trabalhadores. 2. No caso em apreço a recorrente demonstrou satisfatoriamente que ao menos em parte, o valor da conta bloqueada serve para pagamento de seus funcionários e que os valores lá provisionados tinham o condão de saldar o débito trabalhista. 3. Agravo de Instrumento parcialmente provido. (TJPR - 16ª C.Cível - 0013386-13.2022.8.16.0000 - Curitiba - Rel.: DESEMBARGADOR PAULO CEZAR BELLIO - J. 27.06.2022)(TJ-PR - AI: 00133861320228160000 Curitiba 0013386-13.2022.8.16.0000 (Acórdão), Relator: Paulo Cezar Bellio, Data de Julgamento: 27/06/2022, 16ª Câmara Cível, Data de Publicação: 04/07/2022)\nSendo assim, resta claro e incontroverso que eventual constrição realizada prejudicaria sobremaneira a {{NOS}}, pois a aludida penhora recairia sobre suas contas bancárias e, consequentemente, sobre seus recursos financeiros, impossibilitando assim a manutenção de sua atividade empresarial, bem como pagamento dos seus funcionários e fornecedores, causando prejuízos que ultrapassariam os limites da presente demanda.\nPortanto, respeitando-se o Princípio da Menor Onerosidade e o disposto no art. 805 do CPC, a execução deve ser satisfeita mediante a penhora de outros bens pertencentes à empresa executada, conforme demais hipóteses elencadas no art. 835 do Código de Processo Civil, de modo a não causar demasiado prejuízo à {{NOS}}, por ser medida da mais lídima justiça.\nB) Da Violação ao Princípio da Função Social da Empresa\nA função social da empresa consiste em um princípio importante para o devido funcionamento da ordem econômica constitucional, além de contemplar diversas esferas da sociedade, como o meio ambiente, a propriedade privada, o direito dos trabalhadores, entre outros.\nNeste viés, a função social da empresa pode ser conceituada como um princípio que amplia e modifica os interesses e objetivo das sociedades empresárias.\nEste princípio está atrelado à função social da propriedade, trazida pelo artigo 170, inciso II, da Constituição Federal, visto que as empresas se constituem enquanto propriedade privada, devendo, portanto, exercerem sua função social.\nIsto posto, é imperioso destacar que a função social não se confunde com responsabilidade social, visto que, uma empresa socialmente responsável se constitui dessa maneira por mera liberalidade de seu empresário, enquanto que a função social é uma atribuição legislativa, portanto, obrigatória.\nNeste sentido, a adoção de medidas por empresas que visam atender sua função social é capaz de ocasionar diversos desdobramentos, quais sejam: a criação de empregos, pagamento de tributos, geração de riqueza, contribuição para o desenvolvimento econômico, social e cultural do entorno, respeito aos direitos dos consumidores, entre outros.\nSendo assim, a função social também é uma aliada dos empregados, uma vez que de acordo com as garantias previstas pelos artigos 170, inciso VIII e artigo 7º ambos da Constituição Federal, a função social trabalha na proteção dos direitos dos trabalhadores.\nEssa proteção se aplica a partir da garantia de um emprego pleno e digno, além de garantir os direitos fundamentais dos trabalhadores, como salário mínimo, 13º salário, entre outros.\nÀ vista disso, uma vez que esclarecida a importância da existência função social da empresa, é necessário destacar que a determinação de eventual bloqueio de valores nas contas bancárias da {{NOS}}, impossibilitaria a mesma de continuar exercendo sua função social, uma vez que estaria restringida de acessar seus ativos financeiros necessários para a manutenção da atividade empresarial.\nNeste viés, o encerramento das atividades da {{NOS}}, além de ocasionar prejuízo irreparável para a própria, também refletiria em graves prejuízos aos trabalhadores que perderiam seus empregos e, consequentemente não conseguiriam manter suas subsistências e as de suas famílias, ao desenvolvimento econômico da região onde se localiza a empresa, haja vista o aumento da taxa de desemprego, ao Estado que perderia uma fonte de pagamento de tributos, entre diversas outras situações.\nPortanto, não deve ser considerada em momento algum a legalidade de uma eventual constrição de valores nas contas bancárias da {{NOS}}, tendo que em vista que tal medida ocasionaria grave e irreparável violação ao Princípio da Função Social da Empresa, causando prejuízos que vão além do âmbito das partes da presente demanda.", "opcional": true, "padrao": false}, {"chave": "inversao", "titulo": "Da inversão do ônus da prova", "texto": "Claro está o abuso do poder econômico do {{ELES}} em detrimento da {{NOS}}, seja por impor cláusulas abusivas, seja por inserir valores reconhecidamente ilegais por nossos tribunais, o que nos leva a concluir pela presença do requisito verossimilhança das alegações.\nDiante da disparidade de forças, seja financeira e técnica, necessário a inversão do ônus da prova, consonante disposto no artigo 6º, inciso VIII, da Lei Consumerista.\nAdemais, a aplicação do Código de Defesa ao Consumidor aos contratos bancários, pacificados pela edição da Súmula 297 do STJ:\nSúmula 297 – “O Código de Defesa do Consumidor é aplicável às instituições financeiras”.\nPor atração do Código de Defesa ao Consumidor ao caso em tela, corolário lógico é que seja aplicada a inversão do ônus da prova.\nDesta forma, deve ser operada a inversão do ônus da prova, pois, in casu, encontram-se presente os dois requisitos referidos no artigo 6º, inciso VIII, do Código de Defesa do Consumidor ao deferimento da medida excepcional, restando o encargo de eventual fato não comprovado a demanda."}, {"chave": "suspensao", "titulo": "Da suspensão", "texto": "Importante mencionar que há ação revisional em trâmite sob o nº «número da ação revisional», que interferirá diretamente no resultado deste. É possível a conexão entre um processo de conhecimento e um de execução, quando se observar entre eles uma mesma origem, ou seja, que as causas se fundamentam em fatos comuns ou nas mesmas relações jurídicas, sujeitando-as a uma análise conjunta. Conforme jurisprudência:\n\"AGRAVO DE INSTRUMENTO – AÇÃO DE EXECUÇÃO - EMBARGOS À EXECUÇÃO – AÇÃO REVISIONAL PROPOSTA E PENDENTE DE JULGAMENTO – PREJUDICIALIDADE – CONEXÃO - SUSPENSÃO DA EXECUÇÃO – I - Existência de ação revisional ajuizada, em que se discute a validade de diversos títulos, entre os quais o título objeto da ação de execução e dos embargos à execução - Reconhecida a conexão por prejudicialidade entre as demandas – Possibilidade de decisões conflitantes – Inteligência do art. 55, caput, §§s 1º e 2º, I, do NCPC – II - Estando em discussão o título, em sede de ação revisional, é cabível a suspensão da execução, ante a clareza do disposto no art. 313, inciso V, letra 'a', do NCPC – O ajuizamento de ação revisional, cujo objetivo é a discussão do débito exequendo, exerce perante a execução inegável influência prejudicial – Decisão a ser proferida no processo revisional que poderá implicar em eventual redução ou extinção do montante do débito - Inaplicabilidade dos arts. 776 e 784, § 1º, do NCPC, pois a regra geral não prevalece sobre a regra especial (princípio da especialidade) – Hipótese que não se confunde com o art. 919, § 1º, do NCPC - Precedentes deste E. TJ e desta C. 24ª Câmara de Direito Privado – Suspensão da ação de execução reconhecida – Decisão mantida - Agravo improvido.\"\n(TJ-SP 22075157820178260000 SP 2207515-78.2017.8.26.0000, Relator: Salles Vieira, Data de Julgamento: 29/06/2018, 24ª Câmara de Direito Privado, Data de Publicação: 29/06/2018)\nAGRAVO DE INSTRUMENTO. REVISIONAL DE CONTRATO E EXECUÇÃO DE TÍTULO EXTRAJUDICIAL. CONEXÃO. SUSPENSÃO DA EXECUÇÃO ATÉ O TRÂNSITO EM JULGADO DA REVISIONAL DE CONTRATO CUJO TÍTULO EXEQUENDO EM LITÍGIO INTEGRA AÇÃO REVISIONAL DISTINTA. PREJUDICIALIDADE EXTERNA CONFIGURADA. POSSIBILIDADE DA SUSPENSÃO PARA SE EVITAR DECISÕES CONFLITANTES. DECISÃO MANTIDA. RECURSO DESPROVIDO. Conexas as demandas, por cautela cumpre a diligente suspensão da execução até o trânsito em julgado da ação revisional e dos embargos à execução, evitando-se assim, decisões conflitantes. (TJPR - 16ª C.Cível - 0060150-62.2019.8.16.0000 - Loanda - Rel.: Desembargador Luiz Antônio Barry - J. 25.05.2020)\n(TJ-PR - AI: 00601506220198160000 PR 0060150-62.2019.8.16.0000 (Acórdão), Relator: Desembargador Luiz Antônio Barry, Data de Julgamento: 25/05/2020, 16ª Câmara Cível, Data de Publicação: 26/05/2020)\nAGRAVO DE INSTRUMENTO – AÇÃO REVISIONAL DE CONTRATO – DECISÃO AGRAVADA QUE RECONHECEU A CONEXÃO DOS PRESENTES AUTOS COM OS AUTOS DE EXECUÇÃO E DE EMBARGOS À EXECUÇÃO DE TÍTULO EXTRAJUDICIAL. 1. Ação Revisional, Execução de Título Extrajudicial e Embargos à Execução de Título Extrajudicial que possuem como objeto o mesmo contrato - Identidade de partes - Mesma relação contratual – Risco de decisões conflitantes – Conexão - Aplicação do Art. 55, § 3º, do CPC. 2. Decisão mantida. RECURSO NÃO PROVIDO. (TJPR - 14ª C.Cível - 0024294-66.2021.8.16.0000 - Londrina - Rel.: DESEMBARGADOR OCTAVIO CAMPOS FISCHER - J. 30.10.2021)\n(TJ-PR - AI: 00242946620218160000 Londrina 0024294-66.2021.8.16.0000 (Acórdão), Relator: Octavio Campos Fischer, Data de Julgamento: 30/10/2021, 14ª Câmara Cível, Data de Publicação: 03/11/2021)\nSendo assim requer a conexão das ações com efeito suspensivo da ação de execução até o final do julgamento da ação revisional, com fulcro no art. 55, caput, parágrafo 1º e 2, art. 313, V, a, do Código de Processo Civil e entendimento do Tribunal.", "opcional": true, "padrao": false}, {"chave": "pedidos", "titulo": "Dos Pedidos", "texto": "Diante de todo o exposto, requer:\n\nO deferimento do benefício da Justiça Gratuita em favor da {{NOS}}, conforme artigo 98 e seguintes do Código de Processo Civil e, subsidiariamente, caso não seja concedido tal benefício, que as custas sejam recolhidas ao final do processo;\nO recebimento dos embargos monitórios, com a suspensão da eficácia do mandado de pagamento (art. 702, §4º, do CPC);\nA intimação do {{ELES}} para, querendo, apresentar resposta;\nA inversão do ônus da prova, nos termos do artigo 6º, VIII, do Código de Defesa do Consumidor;\nPreliminarmente, a extinção do feito sem resolução do mérito pela ausência de prova escrita e de demonstrativo da evolução do débito (arts. 485, I e IV, e 700 do CPC);\n{{BLOCOS:pedidos}}\nSubsidiariamente, o acolhimento parcial dos embargos para reconhecer o excesso na cobrança, reduzindo o débito ao valor apurado em perícia contábil, com a exibição dos extratos e da planilha de evolução do débito;\nQue seja o {{ELES}} condenado ao pagamento das custas e despesas processuais, bem como de honorários advocatícios de sucumbência;\n\nProtesta provar o alegado através de todos os meios de prova admitidos em direito, em especial a prova pericial contábil.\nDá-se à causa o valor de {{valor_causa}}.\n\nTermos em que,\npede deferimento.\n\n{{escritorio.cidade}}/{{escritorio.uf}}, {{hoje}}.\n\n{{advogado.nome}}\n{{advogado.oab}}"}, {"chave": "provas", "titulo": "ROL DE DOCUMENTOS", "texto": "1. Procuração e atos constitutivos;\n2. Cópia dos documentos que instruem a monitória;\n3. Relatório de revisão contratual com a taxa média do Banco Central (série {{bacen.serie}} — {{bacen.nome}}, {{bacen.mes}});\n{{BLOCOS:provas}}"}]$t$::jsonb, $t${"NOS": "Embargante", "ELES": "Embargado"}$t$::jsonb, true)
on conflict (id) do update set nome = excluded.nome, tipo = excluded.tipo, descricao = excluded.descricao, ordem = excluded.ordem, secoes = excluded.secoes, partes = excluded.partes, numerar = excluded.numerar, updated_at = now();
insert into public.modelos_peca (id, nome, tipo, descricao, ordem, secoes, partes, numerar) values ($t$contestacao_cobranca$t$, $t$Contestação (ação de cobrança bancária)$t$, $t$contestacao$t$, $t$Modelo do escritório: fatos, preliminar de indeferimento da inicial (falta de documentos), CDC, impossibilidade de apuração do valor, Do Direito com as teses, descaracterização da mora, exibição de documentos, prova pericial, gratuidade (opcional), requerimentos.$t$, 27, $t$[{"chave": "enderecamento", "titulo": "", "texto": "EXCELENTÍSSIMO(A) SENHOR(A) DOUTOR(A) JUIZ(A) DE DIREITO DA ___ VARA CÍVEL DA COMARCA DE {{comarca}}\n\nAção de cobrança nº {{processo}}"}, {"chave": "qualificacao", "titulo": "", "texto": "{{cliente.nome}}, pessoa jurídica de direito privado, inscrita no CNPJ sob o nº {{cliente.cnpj}}, com sede em {{cliente.endereco}}, {{cliente.cidade}}/{{cliente.uf}}, neste ato representada por {{cliente.representante}}, {{cliente.representante_qualificacao}}, inscrito(a) no CPF sob o nº {{cliente.representante_cpf}}, já qualificada, vem, respeitosamente, à presença de Vossa Excelência, por seus advogados que esta subscrevem (procuração anexa), nos autos da ação de cobrança em epígrafe, que lhe move {{banco}}, apresentar\n\nCONTESTAÇÃO\n\ne o faz nos seguintes termos:"}, {"chave": "fatos", "titulo": "Dos Fatos", "texto": "O {{ELES}} ingressou com ação de cobrança postulando a condenação da {{NOS}} ao pagamento de {{valor_executado}}, cuja origem seria {{contrato.produto}} ({{contrato.numero}}), firmado em {{contrato.data}}, no valor de {{contrato.valor}}, a ser pago em {{contrato.prazo}} parcelas mensais de {{contrato.parcela}}, com juros de {{contrato.taxa_mensal}} ao mês ({{contrato.taxa_anual}} ao ano).\n{{BLOCOS:fatos}}\nTodavia, a demanda não merece prosperar nos termos aventados na inicial, conforme será demonstrado a seguir."}, {"chave": "preliminar", "titulo": "Da preliminar de indeferimento da inicial: ausência de documentos indispensáveis à propositura da ação", "texto": "Preliminarmente, a {{NOS}} postula pelo indeferimento da petição inicial, pois conforme se verifica dos documentos acostados aos autos, o {{ELES}} não logrou êxito em comprovar a contratação da operação de crédito pela ré.\nNos termos do art. 320 do CPC, “A petição inicial será instruída com os documentos indispensáveis à propositura da ação”. Todavia, no presente caso, a petição inicial não está acompanhada de instrumento indispensável à prova do ato, mais precisamente, o contrato firmado entre as partes que deu origem à dívida e que demonstre quais foram as condições pactuadas.\nMais do que o contrato firmado, sequer há nos autos algum comprovante que demonstre a autorização da {{NOS}} acerca da contratação.\nO que se verifica é tão somente a juntada do extrato referente a «período», sem informações de quais seriam as condições contratadas, de forma que não há como identificar a origem da dívida. Não há nos autos comprovação da taxa de juros contratada e demais encargos incidentes na operação.\nA petição inicial, além da correta delimitação da causa de pedir e do pedido, deve vir acompanhada de documentos considerados indispensáveis para análise da demanda. Sem a juntada de contrato firmado entre as partes ou, ainda, qualquer documento comprobatório da contratação e de suas condições, fica impossível de constatar se os dados da operação ali descritos estão de acordo com o que foi pactuado, inviabilizando inclusive a produção de defesa da parte demandada.\nO art. 373, I, do CPC, é cristalino ao determinar que ao {{ELES}} incumbe o ônus de provar o fato constitutivo do seu direito. Claramente, no caso dos autos, o Banco {{ELES}} não cumpriu com esse ônus.\nNessa linha, o Egrégio Tribunal de Justiça do Estado de «UF», orienta o seu entendimento no sentido de que é ônus do {{ELES}} comprovar a origem do débito e que a constatação do débito na forma cobrada depende do cotejo entre os contratos firmados e os valores indicados nos extratos:\nAPELAÇÃO CÍVEL. NEGÓCIOS JURÍDICOS BANCÁRIOS. AÇÃO DE COBRANÇA. AUSÊNCIA DE PROVA DA ORIGEM DA COBRANÇA. SENTENÇA DE IMPROCEDÊNCIA MANTIDA. Na forma do artigo 373, inciso I, do Código de Processo Civil, o ônus da prova incumbe ao {{ELES}}, quanto ao fato constitutivo de seu direito. Caso em que a parte-autora não se desincumbiu do ônus de comprovar a origem do crédito cobrado, pois deixou de anexar aos autos a cópia dos contratos. A constatação da existência do débito, na forma cobrada pelo {{ELES}}, exige o cotejo entre os contratos firmados e os valores indicados nos extratos. DO PREQUESTIONAMENTO. É desnecessária expressa referência no acórdão de todos os dispositivos legais invocados pelas partes, considerando-se incluídos na decisão. APELAÇÃO DESPROVIDA. (Apelação Cível, Nº 50002946620158210135, Vigésima Câmara Cível, Tribunal de Justiça do RS, Relator: Fernanda Carravetta Vilande, Julgado em: 21-06-2023)\nAnte o exposto, não havendo prova da contratação e dos documentos que comprovam as condições pactuadas, requer a extinção do feito sem resolução de mérito, nos termos do art. 485, I, do CPC.", "opcional": true, "padrao": true}, {"chave": "cdc", "titulo": "Dos fundamentos — da incidência do Código de Defesa do Consumidor", "texto": "Subsidiariamente, caso este MM. Juízo não entenda pela extinção do feito por indeferimento da inicial, postula-se pela análise das questões de mérito abaixo explanadas.\nO caso dos autos trata-se de uma relação de consumo, nos termos da Súmula nº 297, do STJ: “O Código de Defesa do Consumidor é aplicável às instituições financeiras”.\nAssim, estando presentes os elementos que formam a relação jurídica consumerista, quais sejam, a presença do consumidor, do fornecedor, da prestação de um serviço e da vulnerabilidade da {{NOS}} perante o {{ELES}}, é cabível a incidência do Código de Defesa do Consumidor.\nEm decorrência disso, aplica-se o art. 6º, VIII, do CDC, que prevê como direito básico do consumidor, a facilitação da defesa dos seus direitos com a inversão do ônus da prova, o que, desde já, se requer."}, {"chave": "apuracao", "titulo": "Da impossibilidade de apuração do valor devido", "texto": "Outrossim, compulsando os autos, constata-se que, além da ausência de contrato firmado entre as partes, há flagrante irregularidade quanto aos demais documentos acostados aos autos, em especial, quanto à evolução da dívida.\nVeja-se que o {{ELES}} tão somente acostou o que seria o valor devido corrigido e os critérios supostamente utilizados para a atualização do montante em {{valor_executado}}:\n«inserir o demonstrativo apresentado»\nNão há sequer como apurar se a taxa de juros aplicada foi realmente de {{contrato.taxa_mensal}} a.m. e {{contrato.taxa_anual}} a.a., uma vez que se desconhece o valor base utilizado para cálculo da aplicação dos juros.\nAssim, fica a {{NOS}} totalmente impossibilitada de apurar como se deu a incidência dos juros no saldo devedor.\nRepita-se: o demonstrativo do débito deve expor a evolução da dívida de maneira clara, com todas as amortizações, juros cobrados, correção monetária etc. Isso mês a mês, até a propositura da ação. No contexto, não se sabe minimamente quais critérios foram utilizados para se chegar ao valor final do débito; muito menos comprovantes de sua evolução.\nApenas com a documentação apresentada pelo {{ELES}}, mostra-se inviável demonstrar pormenorizadamente as ilegalidades na cobrança dos valores, tais como abusividade nas taxas de juros praticadas, existência de encargos cobrados indevidamente, entre outros.\nDessa forma, no presente caso, não sendo possível analisar as condições iniciais contratadas, bem como a existência de encargos e cobranças indevidas que foram pactuadas no contrato, não há como se apurar o valor devido.\nApenas com a documentação trazida pelo {{ELES}} junto à inicial, fica a {{NOS}} totalmente limitada, podendo ser condenada ao pagamento de uma dívida eivada de vícios e, portanto, nula de pleno direito, razão pela qual improcede a presente demanda por absoluta falta de provas.", "opcional": true, "padrao": true}, {"chave": "direito", "titulo": "Do Direito", "texto": "{{BLOCOS:fundamentos}}"}, {"chave": "exibicao", "titulo": "Da exibição de documentos", "texto": "A {{NOS}} não detém as vias dos contratos celebrados com a parte contrária. No entanto, como já referido, tais documentos são fundamentais para que se avalie a evolução do débito e a regularidade na cobrança dos valores.\nPor essa razão, não entendendo este MM. Juízo pela improcedência da presente demanda, desde já se requer seja o {{ELES}} intimado a apresentar os documentos acima referidos.\nTal pedido encontra guarida no art. 396 e seguintes do CPC, sob as consequências do art. 400 do mesmo diploma legal, bem como já foi objeto de definição do TEMA 411, em repetitivo junto ao STJ:\nAssim, considerando todo o amparo legal e jurisprudencial supracitado, bem como a inversão do ônus da prova assegurada pelo Código de Defesa do Consumidor, postula-se que o {{ELES}} seja intimada a exibir os documentos acima referidos."}, {"chave": "pericia", "titulo": "Da prova pericial", "texto": "A {{NOS}} logrou demonstrar a impossibilidade de se apurar, com precisão, as operações financeiras e suas condições de contratação, bem como a evolução do débito. A perícia, sem dúvida, poderá indicar, de fato, qual o verdadeiro saldo devedor. Trata-se de controvérsia na qual a simples juntada de prova documental não resolve os pontos aventados.\nNesse sentido, foram desenvolvidos inúmeros argumentos de natureza financeira, os quais envolvem o exame do caso concreto, e por isso a necessidade de perícia. Salienta-se que todos os fundamentos são amparados na jurisprudência pacificada no STJ.\nDessa forma, quando acostados aos autos os documentos requeridos pela {{NOS}}, imperiosa a realização de perícia contábil, a fim de que seja revista toda a relação contratual, bem como seja definida qual a taxa de juros mais adequada ao caso concreto."}, {"chave": "gratuidade", "titulo": "Da gratuidade de justiça", "texto": "Inicialmente, importa salientar que a requerente não tem condições de arcar com as despesas desta demanda. Desta maneira, vem requerer os benefícios da gratuidade da justiça, visto que não possui condições de se responsabilizar com as despesas processuais.\nNesse diapasão, importante considerar que o Código de Processo Civil ao revogar parte da Lei nº 1.060/50, instituiu, no art. 99, § 3º, a presunção de veracidade da declaração de pobreza de modo que não se exige do postulante à assistência judiciária gratuita que faça prova de sua miserabilidade, mas meramente que a declare.\nSendo assim, cumpre ressaltar que a possibilidade de concessão da assistência judiciária gratuita a pessoas jurídicas é objeto de Súmula do STJ, in verbis:\nSúmula 481 – “Faz jus ao benefício da justiça gratuita a pessoa jurídica com ou sem fins lucrativos que demonstrar sua impossibilidade de arcar com os encargos processuais.”\nDito isso, salvo circunstâncias especiais, nas quais há evidente demonstração da improcedência da alegada pobreza, em razão de sinais exteriores de riqueza, a mera petição da requerente basta para suprir a exigência legal no deferimento do benefício.\nAdemais, o referido pedido está preconizado no art. 98 e seguintes do Código de Processo Civil e no art. 5º da Constituição Federal, mais especificamente no inciso LXXIV, sendo esta benesse, garantia fundamental ao Estado Democrático de Direito.\nSalienta-se que tal pedido não está sendo feito com base na mera declaração de hipossuficiência da requerente, mas com base na real situação financeira, muito bem demonstrada pela dificuldade de arcar com pagamentos de dívidas.\nAnte ao exposto, roga-se pela concessão dos benefícios da gratuidade da justiça, com fulcro no artigo 98 e seguintes do Código de Processo Civil.", "opcional": true, "padrao": false}, {"chave": "pedidos", "titulo": "Dos Requerimentos", "texto": "Diante do exposto, requer se digne Vossa Excelência de receber e conhecer da presente para o fim de:\n\nDeferir a gratuidade da justiça, nos termos do art. 98 do CPC;\nDeterminar a incidência do Código de Defesa do Consumidor, com a inversão do ônus da prova prevista no art. 6º, VIII, do CDC;\nPreliminarmente, extinguir o feito sem resolução de mérito, haja vista o indeferimento da petição inicial por ausência de documentos necessários ao processamento do feito, de acordo com o art. 485, I e IV, do CPC;\nDeterminar a intimação do {{ELES}} para que exiba o contrato, os extratos bancários e o demonstrativo com a evolução da dívida, demonstrando os encargos e os abatimentos, sob pena de incidência do art. 400 do CPC;\nDeterminar a realização de perícia contábil, a fim de que seja revista toda a relação contratual, bem como definida a taxa de juros adequada ao caso concreto;\nNo mérito, julgar improcedente a ação de cobrança por absoluta falta de provas, uma vez que os documentos comprobatórios das supostas operações estão incompletos;\n{{BLOCOS:pedidos}}\nCondenar o {{ELES}} ao pagamento de custas e honorários sucumbenciais, na forma do art. 85 do Código de Processo Civil;\n\nProtesta provar o alegado por todos os meios de prova admitidos em direito, mais precisamente, prova documental e pericial.\n\nNestes termos, pede deferimento.\n\n{{escritorio.cidade}}/{{escritorio.uf}}, {{hoje}}.\n\n{{advogado.nome}}\n{{advogado.oab}}"}, {"chave": "provas", "titulo": "ROL DE DOCUMENTOS", "texto": "1. Procuração e atos constitutivos;\n2. Relatório de revisão contratual com a taxa média do Banco Central (série {{bacen.serie}} — {{bacen.nome}}, {{bacen.mes}});\n{{BLOCOS:provas}}"}]$t$::jsonb, $t${"NOS": "Ré", "ELES": "Autor"}$t$::jsonb, true)
on conflict (id) do update set nome = excluded.nome, tipo = excluded.tipo, descricao = excluded.descricao, ordem = excluded.ordem, secoes = excluded.secoes, partes = excluded.partes, numerar = excluded.numerar, updated_at = now();
insert into public.modelos_peca (id, nome, tipo, descricao, ordem, secoes, partes, numerar) values ($t$inicial_revisional$t$, $t$Ação revisional de contrato bancário c/c tutela de urgência$t$, $t$inicial$t$, $t$Modelo do escritório: fatos com os dados do contrato, aplicação do CDC, Do Direito com as teses (juros com a leitura do Tema 27, encargos acessórios, capitalização…), depósito do incontroverso, exibição de documentos (opcional), gratuidade (opcional), pedidos.$t$, 10, $t$[{"chave": "enderecamento", "titulo": "", "texto": "AO JUÍZO DE DIREITO DA ___ VARA CÍVEL DA COMARCA DE {{comarca}}"}, {"chave": "qualificacao", "titulo": "", "texto": "{{cliente.nome}}, pessoa jurídica de direito privado, inscrita no CNPJ sob o nº {{cliente.cnpj}}, com sede em {{cliente.endereco}}, {{cliente.cidade}}/{{cliente.uf}}, neste ato representada por {{cliente.representante}}, {{cliente.representante_qualificacao}}, inscrito(a) no CPF sob o nº {{cliente.representante_cpf}}, vem, por seus advogados que esta subscrevem (procuração anexa), com escritório em {{escritorio.endereco}}, {{escritorio.cidade}}/{{escritorio.uf}}, onde recebem intimações, à presença de Vossa Excelência, propor\n\nAÇÃO REVISIONAL DE CONTRATO BANCÁRIO C/C TUTELA DE URGÊNCIA\n\nem face de {{banco}}, instituição financeira inscrita no CNPJ sob o nº {{banco.cnpj}}, com sede em {{banco.endereco}}, pelos fatos e fundamentos a seguir apresentados:"}, {"chave": "fatos", "titulo": "DOS FATOS", "texto": "A {{NOS}} pede vênia para anunciar a esse MM. Juízo que a pretensão ora deduzida está em consonância com o entendimento jurisprudencial pacificado no STJ, em especial em sede de recursos repetitivos.\nO objetivo da presente demanda é fazer a revisão judicial da relação contratual havida entre as partes, tendo por norte justamente os precedentes que vinculam a matéria, e que serão apontados ao longo desta peça.\nAs partes mantêm relacionamento contratual desde «início do relacionamento». Como parte deste relacionamento, celebraram o seguinte contrato de concessão de crédito:\nContrato nº {{contrato.numero}}, modalidade {{contrato.produto}}, celebrado em {{contrato.data}}. Valor do crédito: {{contrato.valor}} ({{contrato.valor_financiado}} financiados). Número de parcelas: {{contrato.prazo}}. Valor das parcelas: {{contrato.parcela}}. Taxa de juros: {{contrato.taxa_mensal}} ao mês e {{contrato.taxa_anual}} ao ano. Custo Efetivo Total: {{contrato.cet}} ao ano.\n{{BLOCOS:fatos}}\nA revisão judicial ora requerida tem por objeto os itens a seguir fundamentados."}, {"chave": "cdc", "titulo": "DA APLICAÇÃO DO CÓDIGO DE DEFESA DO CONSUMIDOR", "texto": "O tema da incidência do Código de Defesa do Consumidor em relações bancárias está pacificado na Súmula 297 do STJ:\nSTJ - Súmula 297 O Código de Defesa do Consumidor é aplicável às instituições financeiras.\nNo caso em tela, é evidente a relação de consumo, pois está presente o requisito da vulnerabilidade do consumidor em suas quatro facetas, a saber:\n(a) Vulnerabilidade informacional\n(b) Vulnerabilidade técnica,\n(c) Vulnerabilidade jurídica\n(d) Vulnerabilidade fática ou socioeconômica\nA {{NOS}} não atua profissionalmente na concessão de crédito. Esta é a atividade profissional do {{ELES}}.\nAssim, estão presentes os elementos que formam a relação jurídica consumerista, quais sejam a presença do consumidor, do fornecedor, da prestação de um serviço e da vulnerabilidade da {{NOS}} perante o {{ELES}}, incidindo a Lei nº 8.078/90, o Código de Defesa do Consumidor:\n“Art. 2° Consumidor é toda pessoa física ou jurídica que adquire ou utiliza produto ou serviço como destinatário final.\n(...)\nArt. 3° Fornecedor é toda pessoa física ou jurídica, pública ou privada, nacional ou estrangeira, bem como os entes despersonalizados, que desenvolvem atividade de produção, montagem, criação, construção, transformação, importação, exportação, distribuição ou comercialização de produtos ou prestação de serviços.\n(...)”\nEstando demonstrada a incidência das normas do direito do consumidor, passa-se aos temas contratuais que se pretende revisar."}, {"chave": "direito", "titulo": "DO DIREITO", "texto": "{{BLOCOS:fundamentos}}"}, {"chave": "deposito", "titulo": "DO DEPÓSITO DO INCONTROVERSO – ART. 330, §§ 2º E 3º, DO CPC", "texto": "Em atendimento ao previsto no artigo 330 §§ 2o e 3o do CPC, a {{NOS}} apresenta a planilha de cálculo em anexo, denominada CÁLCULO DA PRESTAÇÃO, que aponta o valor incontroverso: parcela recalculada pela taxa média de mercado de {{calc.parcela_media}} ({{contrato.prazo}} parcelas), em lugar da parcela contratual de {{contrato.parcela}}.\nA {{NOS}} tem consciência de que a memória de cálculo apresentada é unilateral. Produzida inclusive por exigência de requisito legal.\nPor tal razão registra que a depender da prova técnica, a {{NOS}} reserva-se o direito de readequar sua posição: (i) em se confirmando saldo devedor superior ao apontado inicialmente, promoverá complementação dos depósitos, demonstrando sua boa-fé; (ii) em se confirmando saldo devedor inferior ao apontado inicialmente, pede-se inclusão do excedente a maior no pedido de devolução/compensação.\nAssim sendo, a {{NOS}}, em cumprimento ao requisito legal, informa que depositará nos autos o valor incontroverso, motivo pelo qual requer autorização judicial para abertura de conta judicial vinculada ao feito."}, {"chave": "tutela", "titulo": "DA TUTELA DE URGÊNCIA", "texto": "Presentes a probabilidade do direito, demonstrada pelos cálculos que instruem a inicial, e o perigo de dano, consistente na continuidade dos descontos em conta e na iminente inscrição do nome da {{NOS}} em cadastros restritivos, requer-se, nos termos do art. 300 do CPC, a concessão de tutela de urgência para: (a) autorizar o depósito judicial das parcelas no valor incontroverso de {{calc.parcela_media}}; (b) determinar que o {{ELES}} se abstenha de inscrever, ou mantenha excluído, o nome da {{NOS}} dos cadastros de inadimplentes em relação ao contrato discutido; e (c) determinar que o {{ELES}} se abstenha de realizar débitos automáticos em conta além do valor incontroverso.", "opcional": true, "padrao": true}, {"chave": "exibicao", "titulo": "DA EXIBIÇÃO DE DOCUMENTOS", "texto": "A {{NOS}} não possui os registros completos da contratação, faltando-lhe:\nInstrumentos de contrato;\nExtratos com movimentação do fluxo da operação;\nSaldo devedor atual.\nPor tal razão notificou o {{ELES}} a fim de que lhe ofertasse tais documentos, no entanto, não foi atendido.\nA título de reforço argumentativo, relembra-se se tratar de relação de consumo, em que a inversão do ônus da prova é prevista (art. 6º, CDC), bem como por se tratar o banco de ente submetido a regramento do BACEN, tem o dever de manutenção e guarda de documentos, de modo que lhe incide a hipótese de maior facilidade para apresentação da prova, incidindo também a regra da distribuição dinâmica do ônus da prova (art. 373, § 1º, CPC).\nAssim, pede-se seja o {{ELES}} intimado para que apresente em juízo a totalidade dos registros que envolve a relação contratual das partes, sob as consequências da presunção de veracidade em relação às afirmações constantes nas causas de pedir que seguem, conforme art. 400, do CPC.", "opcional": true, "padrao": false}, {"chave": "gratuidade", "titulo": "DA GRATUIDADE DE JUSTIÇA", "texto": "Inicialmente, importa salientar que a requerente não tem condições de arcar com as despesas desta demanda. Desta maneira, vem requerer os benefícios da gratuidade da justiça, visto que não possui condições de se responsabilizar com as despesas processuais.\nNesse diapasão, importante considerar que o Código de Processo Civil ao revogar parte da Lei nº 1.060/50, instituiu, no art. 99, § 3º, a presunção de veracidade da declaração de pobreza de modo que não se exige do postulante à assistência judiciária gratuita que faça prova de sua miserabilidade, mas meramente que a declare.\nSendo assim, cumpre ressaltar que a possibilidade de concessão da assistência judiciária gratuita a pessoas jurídicas é objeto de Súmula do STJ, in verbis:\nSúmula 481 – “Faz jus ao benefício da justiça gratuita a pessoa jurídica com ou sem fins lucrativos que demonstrar sua impossibilidade de arcar com os encargos processuais.”\nDito isso, salvo circunstâncias especiais, nas quais há evidente demonstração da improcedência da alegada pobreza, em razão de sinais exteriores de riqueza, a mera petição da requerente basta para suprir a exigência legal no deferimento do benefício.\nAdemais, o referido pedido está preconizado no art. 98 e seguintes do Código de Processo Civil e no art. 5º da Constituição Federal, mais especificamente no inciso LXXIV, sendo esta benesse, garantia fundamental ao Estado Democrático de Direito.\nSalienta-se que tal pedido não está sendo feito com base na mera declaração de hipossuficiência da requerente, mas com base na real situação financeira, muito bem demonstrada pela dificuldade de arcar com pagamentos de dívidas.\nAnte ao exposto, roga-se pela concessão dos benefícios da gratuidade da justiça, com fulcro no artigo 98 e seguintes do Código de Processo Civil.", "opcional": true, "padrao": false}, {"chave": "pedidos", "titulo": "DOS PEDIDOS", "texto": "DIANTE DO EXPOSTO, requer seja a presente recebida e conhecida, bem como os documentos que a acompanham, para o fim de:\n\nConceder o benefício da gratuidade da justiça, uma vez que a {{NOS}} não possui condições de arcar com as despesas processuais;\nConceder a tutela de urgência, nos termos requeridos;\nAutorizar a abertura de conta judicial para que a {{NOS}} siga depositando o valor incontroverso, nos termos do art. 330, §§ 2º e 3º, do CPC;\nDeterminar a citação do {{ELES}} para, querendo, apresentar defesa, sob pena de revelia e confissão;\nDeterminar a inversão do ônus da prova, ante a hipossuficiência da {{NOS}} perante o {{ELES}}, nos termos do artigo 6º, VIII, do Código de Defesa do Consumidor;\nDeferir a realização de perícia técnica, de natureza contábil, a fim de que seja fixado o efetivo quantum debeatur, bem como apontada a taxa de juros adequada ao caso concreto;\n{{BLOCOS:pedidos}}\nComo efeito dos provimentos acima requeridos, determinar o recálculo dos valores eventualmente ainda devidos, levando em consideração os depósitos judiciais efetuados no curso do processo, com a restituição ou compensação do que foi pago a maior, devidamente atualizado;\nCondenar o {{ELES}} ao pagamento das custas processuais e honorários sucumbenciais;\nDeferir a produção de provas por todos os meios admitidos em direito, em especial documental e pericial;\n\nAtribui-se à causa o valor de {{valor_causa}}.\n\nNestes termos, pede deferimento.\n\n{{escritorio.cidade}}/{{escritorio.uf}}, {{hoje}}.\n\n{{advogado.nome}}\n{{advogado.oab}}"}, {"chave": "provas", "titulo": "ROL DE DOCUMENTOS", "texto": "1. Procuração e atos constitutivos da {{NOS}};\n2. Contrato / cédula de crédito bancário;\n3. Demonstrativo do Custo Efetivo Total;\n4. Extratos bancários;\n5. Planilha de cálculo da prestação (valor incontroverso);\n6. Relatório de revisão contratual com a taxa média do Banco Central (série {{bacen.serie}} — {{bacen.nome}}, {{bacen.mes}});\n{{BLOCOS:provas}}"}]$t$::jsonb, $t${"NOS": "Autora", "ELES": "Réu"}$t$::jsonb, false)
on conflict (id) do update set nome = excluded.nome, tipo = excluded.tipo, descricao = excluded.descricao, ordem = excluded.ordem, secoes = excluded.secoes, partes = excluded.partes, numerar = excluded.numerar, updated_at = now();
insert into public.blocos_tese (tese, peca, titulo, fatos, fundamentos, pedidos, provas, parecer, rascunho) values ($t$juros_media$t$, $t$inicial$t$, $t$Da taxa de juros remuneratórios acima da média de mercado$t$, $t$Os juros remuneratórios pactuados — {{contrato.taxa_mensal}} ao mês ({{contrato.taxa_anual}} ao ano) — superam a taxa média de mercado apurada pelo Banco Central do Brasil para a modalidade {{bacen.nome}} em {{bacen.mes}}, que era de {{bacen.media_mensal}} ao mês ({{bacen.media_anual}} ao ano): a taxa contratada corresponde a {{bacen.razao}} vezes a média.$t$, $t$O STJ consolidou a posição acerca da possibilidade de revisar os juros remuneratórios no Resp 1.061.530/RS, julgado em 22/10/2008. Dentre outros, extrai-se o tema 27:
Tema 27: É admitida a revisão das taxas de juros remuneratórios em situações excepcionais, desde que caracterizada a relação de consumo e que a abusividade (capaz de colocar o consumidor em desvantagem exagerada (art. 51, §1 º, do CDC) fique cabalmente demonstrada, ante às peculiaridades do julgamento em concreto.
A taxa média de juros, apurada pelo Banco Central, é o referencial básico para aferir a abusividade. Ao longo do tempo, é o principal critério que vem sendo adotado pelas cortes brasileiras.
No caso em tela, à época da celebração do contrato de crédito entre as partes, {{contrato.data}}, a taxa média do mercado para as operações da espécie, segundo o BACEN, era de {{bacen.media_mensal}} ao mês e {{bacen.media_anual}} ao ano, ou seja, valor bem menor do que o pactuado, que foi de {{contrato.taxa_mensal}} ao mês e {{contrato.taxa_anual}} ao ano — {{bacen.razao}} vezes a média de mercado.
No entanto, já no julgado paradigma de 2008, ficou assentado que não basta, pura e simplesmente, fazer uma mera comparação com a média de mercado.
Veja-se, no particular, o trecho em destaque, extraído do voto relatora, Ministra Nancy Andrigui, que é central para que bem se encaminhe o julgamento da presente ação (grifou-se):
“Descartados índices ou taxas fixos, é razoável que os instrumentos para aferição da abusividade sejam buscados no próprio mercado financeiro.
“Assim, a análise da abusividade ganhou muito quando o Banco Central do Brasil passou, em outubro de 1999, a divulgar as taxas médias, ponderadas segundo o volume de crédito concedido, para os juros praticados pelas instituições financeiras nas operações de crédito realizadas com recursos livres (conf. Circular no 2957, de 30.12.1999).”
“A taxa média apresenta vantagens porque é calculada segundo as informações prestadas por diversas instituições financeiras e, por isso, representa as forças do mercado. Ademais, traz embutida em si o custo médio das instituições financeiras e seu lucro médio, ou seja, um 'spread' médio. É certo, ainda, que o cálculo da taxa média não é completo, na medida em que não abrange todas as modalidades de concessão de crédito, mas, sem dúvida, presta-se como parâmetro de tendência das taxas de juros. Assim, dentro do universo regulatório atual, a taxa média constitui o melhor parâmetro para a elaboração de um juízo sobre abusividade.
“Como média, não se pode exigir que todos os empréstimos sejam feitos segundo essa taxa. Se isto ocorresse, a taxa média deixaria de ser o que é, para ser um valor fixo. Há, portanto, que se admitir uma faixa razoável para a variação dos juros.
“Todavia, esta perquirição acerca da abusividade não é estanque, o que impossibilita a adoção de critérios genéricos e universais.
“A taxa média de mercado, divulgada pelo Banco Central, constitui um valioso referencial, mas cabe somente ao juiz, no exame das peculiaridades do caso concreto, avaliar se os juros contratados foram ou não abusivos.”
No mesmo julgamento, o Ministro João Otávio de Noronha, em voto-vista, assim se manifestou ao votar contrário à propositura da relatora, de que se considerasse um critério fixo para aferir a abusividade da taxa de juros, com base em um percentual da taxa média apurada pelo Banco Central (grifou-se):
“A meu sentir, melhor será aferir a abusividade diante do caso concreto, tendo em conta a realidade econômica vigente em determinado local e tempo. Confio que, nas instâncias ordinárias, os julgadores saberão, caso a caso, diagnosticar se está ou não configurada a chamada abusividade dos encargos cobrados para daí, então, descaracterizar ou não a mora.
(...)
Reafirmo: é melhor que o juiz, caso a caso, mediante demonstração cabal da situação, tendo em conta a realidade econômica subjacente ao contrato e às provas dos autos, decida, justificadamente, se há ou não onerosidade da taxa contratada.
(...)
É sabido que o custo do dinheiro varia segundo o tempo, o espaço geográfico, as condições da macroeconomia e outras variáveis. Melhor deixar que tal aferição, ou seja, a da abusividade, fique entregue ao juiz que, diante do caso concreto, tendo em conta a realidade do mercado no momento da contratação, saberá decidir se o consumidor estará ou não sendo prejudicado.
(...)
É por isso, Senhores Ministros, que prefiro confiar na prudência do juiz da causa, que, diante da realidade do caso concreto, saberá adotar a decisão que melhor atenda o equilíbrio contratual e, por conseguinte, beneficie, nos exatos termos da lei, o consumidor probo e honesto.
Em recente acórdão (REsp. 1.821.182/RS – julgado em 29/06/2022, Rel. Ministra Isabel Gallotti), a necessidade de exame do caso concreto foi reiterada:
“4. O caráter abusivo da taxa de juros contratada haverá de ser demonstrado de acordo com as peculiaridades de cada caso concreto (...)”
Neste julgado, a Ministra Isabel Gallotti faz uma crítica ao que considera um desvirtuamento do que ficou definido no julgamento de 2008:
“Tem-se, portanto, que ficou assentado no julgamento do recurso repetitivo (REsp. 1.061.530/RS) que a alteração das taxas de juros remuneratórios pactuadas em contratos bancários depende da demonstração cabal de abuso, o qual deve ser apurado pelo juiz em face do caso concreto, tendo em conta a situação da economia na época da contratação, o custo da captação dos recursos pela instituição financeira credora (esse custo varia entre os agentes do mercado financeiro), e sobretudo o risco envolvido na operação, aqui considerado histórico de crédito do devedor, o relacionamento mantido com o banco, as garantias da operação, entre outras peculiaridades do caso em julgamento.”
“Foi expressamente rejeitada a proposta da Relatora de estabelecer um teto para os juros remuneratórios, fosse ele o dobro ou o triplo da taxa média apurada pelo Banco Central para o mesmo segmento de crédito.”
“A despeito de uniformizada a matéria pela Seção competente do STJ, existe atualmente uma grande dispersão da jurisprudência dos Tribunais Estaduais, quanto ao tema da abusividade dos juros remuneratórios. O que se tem visto é que alguns Tribunais de Justiça limitam as taxas de juros pactuadas à média de mercado, simplesmente porque estão acima da taxa média em operações da mesma natureza, o que implica reconhecimento automático da abusividade pela Corte de origem, ou, ainda, pelo fato de a taxa contratada estar acima de um patamar ou percentual fixo estipulado pela Corte local, o que configuraria a excessividade, sem levar em consideração os custos da específica operação de crédito em questão e a análise do risco envolvido na contratação.”
“Isso significa que, na prática, o tabelamento dos juros que a Segunda Seção julgou indevido e inadequado, tendo em vista a força vinculante dos contratos, o princípio da livre concorrência, e a legislação de regência do mercado financeiro, está sendo realizado, com percentuais máximos diferentes - mas da mesma forma em abstrato, sem consideração das peculiaridades de cada operação de crédito - pelos diversos órgãos jurisdicionais espalhados pelo País.
“Sendo assim, é possível concluir que a utilização somente das taxas divulgadas pelo Banco Central do Brasil como parâmetro único para a indicação da prática de juros abusivos não pode ser aceita.
Dessa forma, a redução das taxas de juros contratadas, pelo Judiciário, somente pelo fato de estarem acima da média de mercado, em atenção às supostas "circunstâncias da causa" não descritas na decisão, - em geral apenas cotejando, de um lado, a taxa contratada e, de outro, o limite aprioristicamente adotado pela Câmara ou Turma em relação à taxa média divulgada pelo Bacen - está em manifesto confronto com a orientação firmada no REsp. 1.061.530/RS.”
Mais recentemente, o STJ tem proferido decisões em que os acórdãos das cortes estaduais têm sido cassados, para que novos julgamentos sejam proferidos, atentando para a necessidade de aferir a abusividade segundo as circunstâncias do caso concreto.
Veja o seguinte exemplo:
RECURSO ESPECIAL. CONTRATO DE MÚTUO BANCÁRIO. JUROS REMUNERATÓRIOS. REVISÃO. CARÁTER ABUSIVO. REQUISITOS. NECESSIDADE DE FUNDAMENTAÇÃO ADEQUADA.
(..)
5- São insuficientes para fundamentar o caráter abusivo dos juros remuneratórios: a) a menção genérica às "circunstâncias da causa" - ou outra expressão equivalente; b) o simples cotejo entre a taxa de juros prevista no contrato e a média de mercado divulgada pelo BACEN e c) a aplicação de algum limite adotado, aprioristicamente, pelo próprio Tribunal estadual.
6- Na espécie, não se extrai do acórdão impugnado qualquer consideração acerca das peculiaridades da hipótese concreta, limitando-se a cotejar as taxas de juros pactuadas com as correspondentes taxas médias de mercado divulgadas pelo BACEN e a aplicar parâmetro abstrato para aferição do caráter abusivo dos juros, impondo-se, desse modo, o retorno dos autos às instâncias ordinárias para que aplique o direito à espécie a partir dos parâmetros delineados pela jurisprudência desta Corte Superior.
(REsp n. 2.009.614/SC, relatora Ministra Nancy Andrighi, Terceira Turma, julgado em 27/9/2022, DJe de 30/9/2022.)
Vale dizer, eventual decisão que conclua pela presença ou não da abusividade com base apenas e tão-somente na comparação com a taxa média de mercado terá sido uma decisão não fundamentada, e com isso violará o disposto no artigo 489 § 1º, incisos II e III do CPC.
No caso em tela, é de todo prudente que se produza a prova pericial, de natureza contábil, a fim de aferir se as taxas de juros praticadas estão alinhadas ao perfil de risco do cliente. Só assim se poderá identificar a configuração da abusividade, amoldando-se a decisão ao já invocado tema 27 dos Recursos Repetitivos do STJ.
A prova técnica deve considerar, entre outros, os seguintes itens:
Custo da captação dos recursos no local e época do contrato;
Valor e prazo do financiamento;
Fontes de renda do cliente;
Garantias ofertadas;
Situação patrimonial
Existência de prévio relacionamento do cliente com a instituição;
Análise do perfil de risco de crédito do tomador;
Histórico de crédito do tomador
Forma de pagamento da operação;
Outros aspectos
«Adaptar ao caso: relacionamento anterior com a instituição, garantias ofertadas, histórico de adimplência e perfil de risco — razões pelas quais a taxa deveria ficar abaixo da média.»
A taxa média de mercado, apurada pelo Banco Central, é o referencial base, e como tal deve ser considerado. No entanto, não deve ser adotado como único critério para verificar a adequação das taxas de juros praticadas no caso concreto. É o que desde já requer, e que será devidamente deduzido nos requerimentos ao final desta peça.$t$, $t$Reconhecer e declarar a abusividade por parte do {{ELES}} ao aplicar taxa de juros acima da taxa média de mercado ao contrato celebrado junto à {{NOS}};
Que seja declarada a abusividade dos juros remuneratórios aplicados no presente contrato, determinando a aplicação da taxa média de juros divulgada pelo Banco Central, qual seja, {{bacen.media_mensal}} ao mês, ou a taxa adequada ao caso concreto apurada em perícia contábil;
A adequação das taxas de juros praticadas no contrato, para que incidam apenas e tão somente aquelas praticadas de acordo com a taxa média de juros, conforme apurado pelo Banco Central;$t$, $t$Série histórica {{bacen.serie}} do SGS/BACEN ({{bacen.nome}})$t$, $t$Os juros do seu contrato ({{contrato.taxa_mensal}} ao mês) estão acima da média que o Banco Central registrou para esse tipo de empréstimo no mês em que você contratou ({{bacen.media_mensal}} ao mês) — {{bacen.razao}} vezes a média. Isso representa cerca de {{calc.dif_media}} de juros a mais ao longo do contrato. A Justiça não reduz juros só porque estão acima da média, mas uma diferença dessa proporção é um bom indício para pedir a revisão.$t$, false)
on conflict (tese, peca) do update set titulo = excluded.titulo, fatos = excluded.fatos, fundamentos = excluded.fundamentos, pedidos = excluded.pedidos, provas = excluded.provas, parecer = excluded.parecer, rascunho = false, updated_at = now() where public.blocos_tese.rascunho;
insert into public.blocos_tese (tese, peca, titulo, fatos, fundamentos, pedidos, provas, parecer, rascunho) values ($t$juros_media$t$, $t$embargos$t$, $t$Da taxa de juros remuneratórios acima da média de mercado$t$, $t$Os juros remuneratórios pactuados — {{contrato.taxa_mensal}} ao mês ({{contrato.taxa_anual}} ao ano) — superam a taxa média de mercado apurada pelo Banco Central do Brasil para a modalidade {{bacen.nome}} em {{bacen.mes}}, que era de {{bacen.media_mensal}} ao mês ({{bacen.media_anual}} ao ano): a taxa contratada corresponde a {{bacen.razao}} vezes a média.$t$, $t$Não se nega em momento algum a celebração do contrato entre a {{NOS}} e o {{ELES}}. Porém, através de uma análise do contrato, foi possível verificar que o {{ELES}} aplicou à operação encargos contratuais ilegais, como a aplicação de taxa de juros acima da taxa média de mercado, refletindo inequívoca abusividade por parte do banco frente ao consumidor de boa-fé, bem como também a aplicação de tarifas ilegais no contrato.
Neste viés, destaca-se que uma análise pericial realizou um comparativo entre as taxas fixadas no contrato e as taxas praticadas pela instituição financeira na operação, sob o prisma de verificar as reais condições acordadas entre as partes.
À vista disso, é importante destacar que o {{ELES}} impôs a {{NOS}} a contratação de juros bancários demasiadamente acima da média de mercado praticado na época da contratação.
Assim, vejamos o que preconiza a Súmula do Superior Tribunal de Justiça, enunciado 296:
Enunciado 296 – “Os juros remuneratórios não cumuláveis com a comissão de permanência, são devidos no período de inadimplência, à taxa média de mercado estipulada pelo Banco Central do Brasil, limitada ao percentual contratado.”
Dessa forma, como resultado da apuração financeira, restou evidente, que o negócio jurídico não foi pautado sob o princípio da boa-fé, vez que, as partes ajustaram um contrato de empréstimo, no valor de {{contrato.valor_financiado}}, a ser pago em {{contrato.prazo}} parcelas de {{contrato.parcela}}, com aplicação de taxa de juros mensais de {{contrato.taxa_mensal}} a.m., sendo que, contudo, a taxa de juros que deveria efetivamente ter sido aplicada seria de {{bacen.media_mensal}} a.m., veja-se:
«inserir print do contrato / planilha»
Nesse sentido, se a taxa de juros contratuais da referida operação financeira respeitasse a taxa média divulgada pelo Banco Central de {{bacen.media_mensal}} a.m., o valor correto de cada prestação seria de {{calc.parcela_media}}, veja-se:
«inserir print do contrato / planilha»
Com o valor da parcela do contrato, a {{NOS}} pagará ao final {{calc.total_contratado}}. Já com o valor de parcela revisada, ao final seria pago o valor de {{calc.total_media}}. Comparando a parcela do contrato e a parcela revisada, ao final a {{NOS}} pagará {{calc.dif_media}} a mais do que deveria pagar por conta das irregularidades do contrato.
Ademais, o Superior Tribunal de Justiça em precedente, tem firmado norma no sentido de que, a ausência de consignação clara do montante de “preço final”, ou seja, a clara identificação da taxa consignada no instrumento do contrato, configura hipótese de aplicação da taxa média de mercado, conforme tema 234, vejamos:
“Nos contratos de mútuo em que a disponibilização do capital é imediata, o montante dos juros remuneratórios praticados deve ser consignado no respectivo instrumento. Ausente a fixação da taxa no contrato, o juiz deve limitar os juros à média de mercado nas operações em espécie, divulgada pelo Bacen, salvo se a taxa cobrada for mais vantajosa para o cliente. Em qualquer hipótese, é possível a correção para a taxa média se for verificada abusividade nos juros remuneratórios praticados.”
Assim sendo, ante todo o exposto, resta claro e incontroverso que o {{ELES}} aplicou ao contrato ora discutido, percentuais acima da média de mercado.$t$, $t$Reconhecer e declarar a abusividade por parte do {{ELES}} ao aplicar taxa de juros acima da taxa média de mercado ao contrato celebrado junto à {{NOS}};
Que seja declarada a abusividade dos juros remuneratórios aplicados no presente contrato, determinando a aplicação da taxa média de juros divulgada pelo Banco Central, qual seja, {{bacen.media_mensal}} ao mês, ou a taxa adequada ao caso concreto apurada em perícia contábil;
A adequação das taxas de juros praticadas no contrato, para que incidam apenas e tão somente aquelas praticadas de acordo com a taxa média de juros, conforme apurado pelo Banco Central;$t$, $t$Série histórica {{bacen.serie}} do SGS/BACEN ({{bacen.nome}})$t$, $t$Os juros do seu contrato ({{contrato.taxa_mensal}} ao mês) estão acima da média que o Banco Central registrou para esse tipo de empréstimo no mês em que você contratou ({{bacen.media_mensal}} ao mês) — {{bacen.razao}} vezes a média. Isso representa cerca de {{calc.dif_media}} de juros a mais ao longo do contrato. A Justiça não reduz juros só porque estão acima da média, mas uma diferença dessa proporção é um bom indício para pedir a revisão.$t$, false)
