insert into public.blocos_tese (tese, peca, titulo, fatos, fundamentos, pedidos, provas, parecer, rascunho) values ($t$cheque_especial_adimplemento$t$, $t$contestacao$t$, $t$Da ilegalidade da utilização de limite de cheque especial para adimplemento do débito$t$, $t$As parcelas do contrato foram debitadas com utilização do limite de cheque especial/conta garantida, com juros muito superiores aos encargos da dívida original — «indicar período e valores».$t$, $t$Analisando o contrato aqui discutido, além da abusividade supramencionada, no tocante a taxa de juros remuneratórios efetivamente aplicada sobre o saldo devedor ser bastante superior à taxa média de mercado, também restou identificada a utilização do limite de cheque especial, para o adimplemento de suas parcelas, veja-se:
